import { submitPverifyEligibilityCheck } from './pverifyService'
import { submitStediEligibilityCheck } from './stediService'
import { env } from '../config/env'
import type {
  IntakeEligibilityForm,
  PverifyEligibilityBuildOptions,
} from './pverifyEligibilityPayload'

export type EligibilityServiceType = 'stedi' | 'pverify'

export type StediConfig = {
  apiUrl: string
  apiKey: string
}

export type PverifyConfig = {
  apiUrl: string
  clientKey: string
  clientSecret: string
  clientApiId: string
  clientUserName: string
  eligibilityPath: string
}

export type EligibilityServiceConfigs = {
  stedi: StediConfig
  pverify: PverifyConfig
}

function safeEnv(read: () => string): string {
  try {
    return read()
  } catch {
    return ''
  }
}

export function buildDefaultServiceConfigs(): EligibilityServiceConfigs {
  return {
    stedi: {
      apiUrl: safeEnv(() => env.stediApiUrl()),
      apiKey: safeEnv(() => env.stediApiKey()),
    },
    pverify: {
      apiUrl: safeEnv(() => env.pverifyApiBase()),
      clientKey: safeEnv(() => env.pverifyClientId()),
      clientSecret: safeEnv(() => env.pverifyClientSecret()),
      clientApiId: safeEnv(() => env.pverifyClientApiId()),
      clientUserName: safeEnv(() => env.pverifyClientUserName()),
      eligibilityPath: safeEnv(() => env.pverifyEligibilityPath()),
    },
  }
}

type SubmitEligibilityArgs = {
  service: EligibilityServiceType
  serviceConfigs: EligibilityServiceConfigs
  formData: IntakeEligibilityForm
  options: PverifyEligibilityBuildOptions
  intakeContext: {
    cptHcpcCode: string
    serviceDateFrom: string
    serviceDateTo: string
    patientName: string
  }
}

export async function submitEligibilityCheck({
  service,
  serviceConfigs,
  formData,
  options,
  intakeContext,
}: SubmitEligibilityArgs): Promise<Record<string, unknown>> {
  if (service === 'pverify') {
    return submitPverifyEligibilityCheck({
      formData,
      options,
      config: serviceConfigs.pverify,
    })
  }
  return submitStediEligibilityCheck({
    formData,
    options,
    config: serviceConfigs.stedi,
    intake: intakeContext,
  })
}
