import { env } from '../config/env'

const POLL_INTERVAL_MS = 1500
const MAX_POLL_ATTEMPTS = 80

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

type OperationStatus = 'notStarted' | 'running' | 'succeeded' | 'failed' | string

function isTerminalStatus(status: OperationStatus): boolean {
  return status === 'succeeded' || status === 'failed'
}

/** Full-document text from Azure `analyzeResult` (REST shape). */
function getAnalyzeResultContent(payload: unknown): string | undefined {
  if (!payload || typeof payload !== 'object') return undefined
  const root = payload as Record<string, unknown>
  const ar = root.analyzeResult
  if (!ar || typeof ar !== 'object') return undefined
  const content = (ar as Record<string, unknown>).content
  return typeof content === 'string' ? content : undefined
}

function logExtractedContentOnce(payload: unknown): void {
  const raw = getAnalyzeResultContent(payload)
  if (raw === undefined) {
    const ar = (payload as Record<string, unknown> | null)?.analyzeResult
    console.log('Azure Document Intelligence — analyzeResult.content:', {
      raw: undefined,
      parsed: undefined,
      note: 'No string `analyzeResult.content`; inspect full `analyzeResult` in prior logs.',
      analyzeResultKeys: ar && typeof ar === 'object' ? Object.keys(ar as object) : [],
    })
    return
  }
  try {
    const parsed = JSON.parse(raw.trim()) as unknown
    console.log('Azure Document Intelligence — analyzeResult.content (JSON.parse):', parsed)
  } catch (err) {
    console.error('Azure Document Intelligence — JSON.parse(raw) failed:', err)
    console.log('Azure Document Intelligence — raw string (not valid JSON):', raw)
  }
}

/**
 * Starts analysis from a public image URL (e.g. Cloudinary `secure_url`), then polls
 * the `Operation-Location` URL until the job finishes.
 *
 * Requires `VITE_AZURE_DOC_INTEL_KEY` (Ocp-Apim-Subscription-Key). Any `VITE_*`
 * value is bundled for the browser — use a backend proxy in production.
 */
export async function analyzeHealthInsuranceCardFromUrl(fileUrl: string): Promise<unknown> {
  const analyzeUrl = env.azureDocIntelAnalyzeUrl()
  const key = env.azureDocIntelKey()

  const res = await fetch(analyzeUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Ocp-Apim-Subscription-Key': key,
    },
    body: JSON.stringify({ urlSource: fileUrl }),
  })

  const operationLocation =
    res.headers.get('operation-location') ?? res.headers.get('Operation-Location')

  const rawBody = await res.text()
  let analyzeBody: unknown = rawBody
  try {
    analyzeBody = rawBody ? JSON.parse(rawBody) : null
  } catch {
    analyzeBody = rawBody
  }

  console.log('Azure Document Intelligence — analyze (POST) response:', {
    status: res.status,
    statusText: res.statusText,
    ok: res.ok,
    operationLocation,
    body: analyzeBody,
  })

  if (res.status !== 202 || !res.ok) {
    throw new Error(
      `Azure Document Intelligence analyze POST expected 202; got ${res.status} ${res.statusText}`
    )
  }

  if (!operationLocation) {
    throw new Error(
      'Azure Document Intelligence analyze: missing Operation-Location header (cannot poll results).'
    )
  }

  let lastPayload: unknown

  for (let attempt = 1; attempt <= MAX_POLL_ATTEMPTS; attempt++) {
    const pollRes = await fetch(operationLocation, {
      method: 'GET',
      headers: {
        'Ocp-Apim-Subscription-Key': key,
      },
    })

    const pollRaw = await pollRes.text()
    let pollJson: Record<string, unknown> | null = null
    try {
      pollJson = pollRaw ? (JSON.parse(pollRaw) as Record<string, unknown>) : null
    } catch {
      console.log('Azure Document Intelligence — analyze result (GET) non-JSON body:', pollRaw)
    }

    const opStatus = (pollJson?.status as OperationStatus | undefined) ?? ''

    console.log('Azure Document Intelligence — analyze result (GET):', {
      attempt,
      httpStatus: pollRes.status,
      httpOk: pollRes.ok,
      status: opStatus || undefined,
      response: pollJson ?? pollRaw,
    })

    if (!pollRes.ok) {
      throw new Error(
        `Azure Document Intelligence result GET failed: ${pollRes.status} ${pollRes.statusText}`
      )
    }

    lastPayload = pollJson ?? pollRaw

    if (opStatus && isTerminalStatus(opStatus)) {
      if (opStatus === 'failed') {
        throw new Error(
          `Azure Document Intelligence analysis failed: ${JSON.stringify(lastPayload)}`
        )
      }
      logExtractedContentOnce(lastPayload)
      return lastPayload
    }

    await sleep(POLL_INTERVAL_MS)
  }

  throw new Error(
    `Azure Document Intelligence: result did not complete after ${MAX_POLL_ATTEMPTS} polls. Last payload: ${JSON.stringify(lastPayload)}`
  )
}
