import { useState, useMemo, DragEvent, ChangeEvent, FormEvent, useEffect } from 'react'
import { Search, Upload, Download, Filter, Plus } from 'lucide-react'
import Select from '../components/forms/Select'
import Button from '../components/forms/Button'
import Input from '../components/forms/Input'
import { apiJsonRequest } from '../services/apiClient'
import { useToast } from '../contexts/ToastContext'
import {
  productServiceOptions,
  categoryOptions,
  authorizationOptions,
} from '../data/cptHcpcData'

interface CptHcpcCode {
  id: string
  code: string
  description: string
  authorizationRequired: boolean
  productService: string
  category: string
}

type ApiCptHcpcCode = {
  id?: string
  code?: string
  cpt_hcpc_code?: string
  description?: string
  authorization_required?: boolean | string
  authorizationRequired?: boolean | string
  product_service?: string
  productService?: string
  category?: string
}

type ApiCptHcpcResponse = {
  data?: ApiCptHcpcCode[] | { codes?: ApiCptHcpcCode[] }
}

type CreateCptHcpcResponse = {
  data?: ApiCptHcpcCode
  message?: string
}

const CptHcpcConfiguration = () => {
  const { showToast } = useToast()
  const [codes, setCodes] = useState<CptHcpcCode[]>([])
  const [isLoadingCodes, setIsLoadingCodes] = useState(false)
  const [searchTerm, setSearchTerm] = useState<string>('')
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [selectedAuthorization, setSelectedAuthorization] = useState<string>('all')
  const [selectedProductService, setSelectedProductService] = useState<string>('all')
  const [showUploadModal, setShowUploadModal] = useState<boolean>(false)
  const [showAddModal, setShowAddModal] = useState<boolean>(false)
  const [dragActive, setDragActive] = useState<boolean>(false)
  
  // Form state for manual add
  const [newCode, setNewCode] = useState({
    code: '',
    description: '',
    category: 'CPT',
    authorizationRequired: 'yes',
    productService: '',
  })
  const [formErrors, setFormErrors] = useState<Record<string, string>>({})
  const [isSubmittingCode, setIsSubmittingCode] = useState(false)

  useEffect(() => {
    const normalizeAuthorization = (value: unknown): boolean => {
      if (typeof value === 'boolean') return value
      if (typeof value === 'string') {
        const v = value.trim().toLowerCase()
        return v === 'true' || v === 'yes' || v === 'required' || v === '1'
      }
      return false
    }

    const normalizeCategory = (value: unknown): string => {
      const raw = typeof value === 'string' ? value.trim().toUpperCase() : ''
      return raw === 'HCPC' ? 'HCPC' : 'CPT'
    }

    const normalizeProductService = (value: unknown): string => {
      const raw = typeof value === 'string' ? value.trim() : ''
      if (!raw) return 'other'
      const matched = productServiceOptions.find(
        (option) => option.value.toLowerCase() === raw.toLowerCase()
      )
      return matched?.value ?? 'other'
    }

    const normalizeCode = (row: ApiCptHcpcCode, index: number): CptHcpcCode => ({
      id: row.id || `code-${index + 1}`,
      code: row.code || row.cpt_hcpc_code || '',
      description: row.description || '',
      authorizationRequired: normalizeAuthorization(
        row.authorizationRequired ?? row.authorization_required
      ),
      productService: normalizeProductService(row.productService ?? row.product_service),
      category: normalizeCategory(row.category),
    })

    const loadCodes = async () => {
      setIsLoadingCodes(true)
      try {
        const response = await apiJsonRequest<ApiCptHcpcResponse | ApiCptHcpcCode[]>(
          '/cpt-hcpc-codes',
          { method: 'GET' }
        )
        const maybeArray = Array.isArray(response)
          ? response
          : Array.isArray(response?.data)
            ? response.data
            : Array.isArray(response?.data?.codes)
              ? response.data.codes
              : []
        setCodes(maybeArray.map((row, index) => normalizeCode(row, index)))
      } catch (error) {
        showToast(error instanceof Error ? error.message : 'Unable to load CPT/HCPC codes.', {
          type: 'error',
          duration: 5000,
        })
      } finally {
        setIsLoadingCodes(false)
      }
    }

    loadCodes()
  }, [showToast])

  // Filter codes based on search and filters
  const filteredCodes = useMemo(() => {
    return codes.filter((code) => {
      const matchesSearch =
        code.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
        code.description.toLowerCase().includes(searchTerm.toLowerCase())

      const matchesCategory =
        selectedCategory === 'all' || code.category === selectedCategory

      const matchesAuthorization =
        selectedAuthorization === 'all' ||
        (selectedAuthorization === 'required' && code.authorizationRequired) ||
        (selectedAuthorization === 'not-required' && !code.authorizationRequired)

      const matchesProductService =
        selectedProductService === 'all' ||
        code.productService === selectedProductService

      return (
        matchesSearch &&
        matchesCategory &&
        matchesAuthorization &&
        matchesProductService
      )
    })
  }, [codes, searchTerm, selectedCategory, selectedAuthorization, selectedProductService])

  const handleProductServiceChange = (codeId: string, newProductService: string) => {
    setCodes((prev) =>
      prev.map((code) =>
        code.id === codeId ? { ...code, productService: newProductService } : code
      )
    )
  }

  const handleDrag = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true)
    } else if (e.type === 'dragleave') {
      setDragActive(false)
    }
  }

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      // Placeholder for file handling
      console.log('File dropped:', e.dataTransfer.files[0])
      // In a real implementation, you would process the CSV file here
    }
  }

  const handleFileInput = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      // Placeholder for file handling
      console.log('File selected:', e.target.files[0])
      // In a real implementation, you would process the CSV file here
    }
  }

  const handleAddCodeInputChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target
    setNewCode((prev) => ({
      ...prev,
      [name]: value,
    }))
    // Clear error for this field when user starts typing
    if (formErrors[name]) {
      setFormErrors((prev) => {
        const newErrors = { ...prev }
        delete newErrors[name]
        return newErrors
      })
    }
  }

  const validateForm = (): boolean => {
    const errors: Record<string, string> = {}
    
    if (!newCode.code.trim()) {
      errors.code = 'Code is required'
    }
    
    if (!newCode.description.trim()) {
      errors.description = 'Description is required'
    }
    
    if (!newCode.productService) {
      errors.productService = 'Product/Service is required'
    }
    
    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  const handleAddCodeSubmit = async (e: FormEvent) => {
    e.preventDefault()
    
    if (!validateForm()) {
      return
    }
    
    // Check if code already exists
    const codeExists = codes.some(
      (code) => code.code.toLowerCase() === newCode.code.trim().toLowerCase()
    )
    
    if (codeExists) {
      setFormErrors({ code: 'This code already exists' })
      return
    }
    
    setIsSubmittingCode(true)
    try {
      const payload = {
        code: newCode.code.trim(),
        category: newCode.category,
        description: newCode.description.trim(),
        authorization_required: newCode.authorizationRequired === 'yes',
        product_service_slug: newCode.productService,
      }
      const response = await apiJsonRequest<CreateCptHcpcResponse>('/cpt-hcpc-codes', {
        method: 'POST',
        body: JSON.stringify(payload),
      })
      const created = response?.data
      const codeToAdd: CptHcpcCode = {
        id: created?.id || `${Date.now()}`,
        code: created?.code || payload.code,
        description: created?.description || payload.description,
        category: (created?.category || payload.category || 'CPT').toUpperCase(),
        authorizationRequired:
          typeof created?.authorization_required === 'boolean'
            ? created.authorization_required
            : payload.authorization_required,
        productService: created?.product_service || payload.product_service_slug,
      }
      setCodes((prev) => [...prev, codeToAdd])
      setNewCode({
        code: '',
        description: '',
        category: 'CPT',
        authorizationRequired: 'yes',
        productService: '',
      })
      setFormErrors({})
      setShowAddModal(false)
      showToast(response?.message || 'CPT / HCPC code created successfully.', { type: 'success' })
    } catch (error) {
      showToast(error instanceof Error ? error.message : 'Unable to create CPT / HCPC code.', {
        type: 'error',
        duration: 5000,
      })
    } finally {
      setIsSubmittingCode(false)
    }
  }

  const handleCloseAddModal = () => {
    setShowAddModal(false)
    setNewCode({
      code: '',
      description: '',
      category: 'CPT',
      authorizationRequired: 'yes',
      productService: '',
    })
    setFormErrors({})
  }

  return (
    <div className="p-4 sm:p-6 space-y-4 sm:space-y-6">
      {/* Page Header */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div className="min-w-0">
          <h1 className="text-xl sm:text-2xl font-bold text-gray-900">
            CPT / HCPC Configuration
          </h1>
          <p className="text-gray-600 mt-1 text-sm sm:text-base">
            Manage CPT and HCPC codes, descriptions, and authorization requirements
          </p>
        </div>
        <div className="flex flex-col sm:flex-row flex-wrap gap-2 w-full lg:w-auto lg:justify-end">
          <Button
            variant="primary"
            onClick={() => setShowAddModal(true)}
            className="w-full sm:w-auto justify-center"
          >
            <div className="flex items-center justify-center">
              <Plus size={18} className="mr-2" />
              Add New
            </div>
          </Button>
          <Button
            variant="outline"
            onClick={() => setShowUploadModal(true)}
            className="w-full sm:w-auto justify-center"
          >
            <div className="flex items-center justify-center">
              <Upload size={18} className="mr-2" />
              Bulk Upload
            </div>
          </Button>
          <Button variant="outline" className="w-full sm:w-auto justify-center">
            <div className="flex items-center justify-center">
              <Download size={18} className="mr-2" />
              Export CSV
            </div>
          </Button>
        </div>
      </div>

      {/* Search and Filters */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 space-y-4">
        {/* Search Bar */}
        <div className="relative">
          <Search
            size={18}
            className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
          />
          <input
            type="text"
            placeholder="Search by code or description..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
          />
        </div>

        {/* Filter Row */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Select
            label="Category"
            name="category"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            options={categoryOptions}
          />

          <Select
            label="Authorization Required"
            name="authorization"
            value={selectedAuthorization}
            onChange={(e) => setSelectedAuthorization(e.target.value)}
            options={authorizationOptions}
          />

          <Select
            label="Product/Service"
            name="productService"
            value={selectedProductService}
            onChange={(e) => setSelectedProductService(e.target.value)}
            options={[
              { value: 'all', label: 'All Products/Services' },
              ...productServiceOptions,
            ]}
          />
        </div>

        {/* Active Filters Indicator */}
        {(selectedCategory !== 'all' ||
          selectedAuthorization !== 'all' ||
          selectedProductService !== 'all' ||
          searchTerm) && (
          <div className="flex flex-wrap items-center gap-2 pt-2 border-t border-gray-200">
            <Filter size={16} className="text-gray-500" />
            <span className="text-sm text-gray-600">Active filters:</span>
            {selectedCategory !== 'all' && (
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-primary-100 text-primary-800">
                Category: {categoryOptions.find((o) => o.value === selectedCategory)?.label}
              </span>
            )}
            {selectedAuthorization !== 'all' && (
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-primary-100 text-primary-800">
                {authorizationOptions.find((o) => o.value === selectedAuthorization)?.label}
              </span>
            )}
            {selectedProductService !== 'all' && (
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-primary-100 text-primary-800">
                {productServiceOptions.find((o) => o.value === selectedProductService)?.label}
              </span>
            )}
            {searchTerm && (
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-primary-100 text-primary-800">
                Search: {searchTerm}
              </span>
            )}
            <button
              onClick={() => {
                setSearchTerm('')
                setSelectedCategory('all')
                setSelectedAuthorization('all')
                setSelectedProductService('all')
              }}
              className="text-sm text-primary-600 hover:text-primary-800 font-medium"
            >
              Clear all
            </button>
          </div>
        )}
      </div>

      {/* Codes Table */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
        {isLoadingCodes && (
          <div className="px-4 sm:px-6 py-3 text-sm text-gray-500 border-b border-gray-200 bg-gray-50">
            Loading CPT / HCPC codes...
          </div>
        )}
        {filteredCodes.length === 0 ? (
          <div className="px-4 sm:px-6 py-8 text-center text-gray-500">
            No codes found matching your search criteria.
          </div>
        ) : (
          <>
            <div className="hidden md:block overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-4 lg:px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Code
                    </th>
                    <th className="px-4 lg:px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Category
                    </th>
                    <th className="px-4 lg:px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Description
                    </th>
                    <th className="px-4 lg:px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Authorization Required
                    </th>
                    <th className="px-4 lg:px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Product/Service
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredCodes.map((code) => (
                    <tr key={code.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-4 lg:px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          {code.code}
                        </div>
                      </td>
                      <td className="px-4 lg:px-6 py-4 whitespace-nowrap">
                        <span
                          className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                            code.category === 'CPT'
                              ? 'bg-blue-100 text-blue-800'
                              : 'bg-purple-100 text-purple-800'
                          }`}
                        >
                          {code.category}
                        </span>
                      </td>
                      <td className="px-4 lg:px-6 py-4">
                        <div className="text-sm text-gray-900 max-w-md">
                          {code.description}
                        </div>
                      </td>
                      <td className="px-4 lg:px-6 py-4 whitespace-nowrap">
                        <span
                          className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                            code.authorizationRequired
                              ? 'bg-yellow-100 text-yellow-800'
                              : 'bg-green-100 text-green-800'
                          }`}
                        >
                          {code.authorizationRequired ? 'Yes' : 'No'}
                        </span>
                      </td>
                      <td className="px-4 lg:px-6 py-4 whitespace-nowrap">
                        <select
                          value={code.productService}
                          onChange={(e) =>
                            handleProductServiceChange(code.id, e.target.value)
                          }
                          className="text-sm border border-gray-300 rounded-lg px-3 py-1.5 max-w-[12rem] lg:max-w-none focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white"
                        >
                          {productServiceOptions.map((option) => (
                            <option key={option.value} value={option.value}>
                              {option.label}
                            </option>
                          ))}
                        </select>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="md:hidden divide-y divide-gray-200">
              {filteredCodes.map((code) => (
                <div key={code.id} className="p-4 space-y-3">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">Code</p>
                      <p className="text-base font-semibold text-gray-900 font-mono mt-0.5">{code.code}</p>
                    </div>
                    <span
                      className={`inline-flex shrink-0 px-2 py-1 text-xs font-semibold rounded-full ${
                        code.category === 'CPT'
                          ? 'bg-blue-100 text-blue-800'
                          : 'bg-purple-100 text-purple-800'
                      }`}
                    >
                      {code.category}
                    </span>
                  </div>
                  <div>
                    <p className="text-xs font-medium text-gray-500">Description</p>
                    <p className="text-sm text-gray-900 mt-1">{code.description}</p>
                  </div>
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div>
                      <p className="text-xs text-gray-500 mb-1">Authorization required</p>
                      <span
                        className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                          code.authorizationRequired
                            ? 'bg-yellow-100 text-yellow-800'
                            : 'bg-green-100 text-green-800'
                        }`}
                      >
                        {code.authorizationRequired ? 'Yes' : 'No'}
                      </span>
                    </div>
                  </div>
                  <div>
                    <label className="text-xs font-medium text-gray-500 block mb-1.5">
                      Product / Service
                    </label>
                    <select
                      value={code.productService}
                      onChange={(e) =>
                        handleProductServiceChange(code.id, e.target.value)
                      }
                      className="w-full text-sm border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent bg-white"
                    >
                      {productServiceOptions.map((option) => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Results Count */}
        {filteredCodes.length > 0 && (
          <div className="px-4 sm:px-6 py-4 border-t border-gray-200 bg-gray-50">
            <p className="text-sm text-gray-600">
              Showing <span className="font-medium">{filteredCodes.length}</span>{' '}
              of <span className="font-medium">{codes.length}</span> codes
            </p>
          </div>
        )}
      </div>

      {/* Add New Code Modal */}
      {showAddModal && (
        <div
          className="fixed inset-0 z-50 overflow-y-auto"
          aria-labelledby="modal-title"
          role="dialog"
          aria-modal="true"
        >
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity"
            onClick={handleCloseAddModal}
          ></div>

          {/* Modal */}
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="relative bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header */}
              <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
                <h3 className="text-lg font-semibold text-gray-900">
                  Add New CPT / HCPC Code
                </h3>
                <button
                  onClick={handleCloseAddModal}
                  className="text-gray-400 hover:text-gray-500 transition-colors"
                >
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              </div>

              {/* Content */}
              <form onSubmit={handleAddCodeSubmit}>
                <div className="px-6 py-6">
                  <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <Input
                        label="Code"
                        name="code"
                        value={newCode.code}
                        onChange={handleAddCodeInputChange}
                        placeholder="e.g., 99213"
                        error={formErrors.code}
                        required
                      />
                      <Select
                        label="Category"
                        name="category"
                        value={newCode.category}
                        onChange={handleAddCodeInputChange}
                        options={categoryOptions.filter((opt) => opt.value !== 'all')}
                        error={formErrors.category}
                        required
                      />
                    </div>

                    <div>
                      <label
                        htmlFor="description"
                        className="block text-sm font-medium text-gray-700 mb-2"
                      >
                        Description <span className="text-red-500">*</span>
                      </label>
                      <textarea
                        id="description"
                        name="description"
                        value={newCode.description}
                        onChange={handleAddCodeInputChange}
                        placeholder="Enter code description..."
                        rows={3}
                        className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 transition-colors ${
                          formErrors.description
                            ? 'border-red-300 focus:ring-red-500 focus:border-red-500'
                            : 'border-gray-300 focus:ring-primary-500 focus:border-primary-500'
                        } bg-white`}
                      />
                      {formErrors.description && (
                        <p className="mt-1 text-sm text-red-600">
                          {formErrors.description}
                        </p>
                      )}
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <Select
                        label="Authorization Required"
                        name="authorizationRequired"
                        value={newCode.authorizationRequired}
                        onChange={handleAddCodeInputChange}
                        options={[
                          { value: 'yes', label: 'Yes' },
                          { value: 'no', label: 'No' },
                        ]}
                        error={formErrors.authorizationRequired}
                        required
                      />
                      <Select
                        label="Product/Service"
                        name="productService"
                        value={newCode.productService}
                        onChange={handleAddCodeInputChange}
                        options={productServiceOptions}
                        placeholder="Select Product/Service"
                        error={formErrors.productService}
                        required
                      />
                    </div>
                  </div>
                </div>

                {/* Footer */}
                <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-200">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={handleCloseAddModal}
                  >
                    Cancel
                  </Button>
                  <Button type="submit" variant="primary" disabled={isSubmittingCode}>
                    {isSubmittingCode ? 'Adding...' : 'Add Code'}
                  </Button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Upload Modal */}
      {showUploadModal && (
        <div
          className="fixed inset-0 z-50 overflow-y-auto"
          aria-labelledby="modal-title"
          role="dialog"
          aria-modal="true"
        >
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity"
            onClick={() => setShowUploadModal(false)}
          ></div>

          {/* Modal */}
          <div className="flex min-h-full items-center justify-center p-4">
            <div
              className="relative bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header */}
              <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
                <h3 className="text-lg font-semibold text-gray-900">
                  Bulk Upload CPT / HCPC Codes
                </h3>
                <button
                  onClick={() => setShowUploadModal(false)}
                  className="text-gray-400 hover:text-gray-500 transition-colors"
                >
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              </div>

              {/* Content */}
              <div className="px-6 py-6">
                <div className="space-y-4">
                  <div>
                    <p className="text-sm text-gray-600 mb-4">
                      Upload a CSV file containing CPT/HCPC codes. The file should
                      include columns for: Code, Description, Authorization Required
                      (Yes/No), and Product/Service.
                    </p>

                    {/* Drop Zone */}
                    <div
                      onDragEnter={handleDrag}
                      onDragLeave={handleDrag}
                      onDragOver={handleDrag}
                      onDrop={handleDrop}
                      className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
                        dragActive
                          ? 'border-primary-500 bg-primary-50'
                          : 'border-gray-300 bg-gray-50'
                      }`}
                    >
                      <Upload
                        size={48}
                        className={`mx-auto mb-4 ${
                          dragActive ? 'text-primary-500' : 'text-gray-400'
                        }`}
                      />
                      <p className="text-sm text-gray-600 mb-2">
                        <span className="font-medium text-primary-600">
                          Click to upload
                        </span>{' '}
                        or drag and drop
                      </p>
                      <p className="text-xs text-gray-500">
                        CSV file (max. 10MB)
                      </p>
                      <input
                        type="file"
                        accept=".csv"
                        onChange={handleFileInput}
                        className="hidden"
                        id="csv-upload"
                      />
                      <label
                        htmlFor="csv-upload"
                        className="mt-4 inline-block"
                      >
                        <Button variant="primary" size="sm" type="button">
                          Select File
                        </Button>
                      </label>
                    </div>
                  </div>

                  {/* Sample Format */}
                  <div className="bg-gray-50 rounded-lg p-4">
                    <h4 className="text-sm font-medium text-gray-900 mb-2">
                      Expected CSV Format:
                    </h4>
                    <div className="overflow-x-auto">
                      <table className="min-w-full text-xs">
                        <thead>
                          <tr className="bg-white">
                            <th className="px-3 py-2 text-left border border-gray-300">
                              Code
                            </th>
                            <th className="px-3 py-2 text-left border border-gray-300">
                              Description
                            </th>
                            <th className="px-3 py-2 text-left border border-gray-300">
                              Authorization Required
                            </th>
                            <th className="px-3 py-2 text-left border border-gray-300">
                              Product/Service
                            </th>
                          </tr>
                        </thead>
                        <tbody>
                          <tr>
                            <td className="px-3 py-2 border border-gray-300 bg-white">
                              99213
                            </td>
                            <td className="px-3 py-2 border border-gray-300 bg-white">
                              Office visit
                            </td>
                            <td className="px-3 py-2 border border-gray-300 bg-white">
                              Yes
                            </td>
                            <td className="px-3 py-2 border border-gray-300 bg-white">
                              office-visit
                            </td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </div>

              {/* Footer */}
              <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-200">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setShowUploadModal(false)}
                >
                  Cancel
                </Button>
                <Button type="button" variant="primary" disabled>
                  Upload
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default CptHcpcConfiguration

