import type {
  IntakeEligibilityForm,
  PverifyEligibilityBuildOptions,
} from './pverifyEligibilityPayload'
import { buildPverifyEligibilityRequestBody } from './pverifyEligibilityPayload'
import { apiRequest } from './apiClient'
import { getSettingsFull } from './settingsService'

type PverifyServiceConfig = {
  apiUrl: string
  clientKey: string
  clientSecret: string
  clientApiId: string
  clientUserName: string
  eligibilityPath: string
}

export type PverifyPayerRow = {
  payerName: string
  payerCode: string
}

type TokenResponse = {
  access_token: string
  expires_in: number
}

type CacheValue = {
  token: string
  expiresAtMs: number
}

const tokenCache = new Map<string, CacheValue>()
const SKEW_MS = 45_000

function cacheKey(config: PverifyServiceConfig) {
  return `${config.apiUrl}|${config.clientKey}|${config.clientApiId}`
}

async function fetchToken(config: PverifyServiceConfig): Promise<string> {
  const key = cacheKey(config)
  const now = Date.now()
  const hit = tokenCache.get(key)
  if (hit && hit.expiresAtMs > now + SKEW_MS) return hit.token
  if (!config.clientKey.trim() || !config.clientSecret.trim()) {
    throw new Error('pVerify client key and secret must be configured in Settings.')
  }
  const body = new URLSearchParams({
    grant_type: 'client_credentials',
    client_id: config.clientKey.trim(),
    client_secret: config.clientSecret.trim(),
  })
  const tokenUrl = `${config.apiUrl.replace(/\/$/, '')}/Token`
  const res = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  })
  const text = await res.text()
  let parsed: TokenResponse | null = null
  try {
    parsed = JSON.parse(text) as TokenResponse
  } catch {
    throw new Error(`pVerify token endpoint returned invalid JSON (${res.status}).`)
  }
  if (!res.ok || !parsed?.access_token) {
    throw new Error('Failed to authenticate with pVerify. Verify key/secret and API URL.')
  }
  tokenCache.set(key, {
    token: parsed.access_token,
    expiresAtMs: now + Math.max(0, parsed.expires_in ?? 0) * 1000,
  })
  return parsed.access_token
}

function buildHeaders(token: string, config: PverifyServiceConfig): HeadersInit {
  const apiId = config.clientApiId.trim() || config.clientKey.trim()
  if (!apiId) throw new Error('pVerify Client API ID (or Client Key) is required.')
  return {
    Authorization: `Bearer ${token}`,
    'Client-API-Id': apiId,
    'Content-Type': 'application/json',
    ...(config.clientUserName.trim()
      ? { 'Client-User-Name': config.clientUserName.trim() }
      : {}),
  }
}

function parseErrorMessage(bodyText: string, status: number): string {
  try {
    const parsed = JSON.parse(bodyText) as {
      message?: string
      error?: string
      error_description?: string
      errors?: string[]
    }
    if (Array.isArray(parsed.errors) && parsed.errors.length) return parsed.errors.join('; ')
    return (
      parsed.message ||
      parsed.error_description ||
      parsed.error ||
      `pVerify eligibility request failed (${status})`
    )
  } catch {
    return bodyText || `pVerify eligibility request failed (${status})`
  }
}

export async function submitPverifyEligibilityCheck(args: {
  formData: IntakeEligibilityForm
  options: PverifyEligibilityBuildOptions
  config: PverifyServiceConfig
}): Promise<Record<string, unknown>> {
  const { config, formData, options } = args
  if (!config.apiUrl.trim()) throw new Error('pVerify API URL is not configured in Settings.')
  const token = await fetchToken(config)
  const path = config.eligibilityPath.trim() || '/api/EligibilitySummary'
  const res = await fetch(`${config.apiUrl.replace(/\/$/, '')}${path}`, {
    method: 'POST',
    headers: buildHeaders(token, config),
    body: JSON.stringify(buildPverifyEligibilityRequestBody(formData, options)),
  })
  const text = await res.text()
  if (!res.ok) {
    throw new Error(parseErrorMessage(text, res.status))
  }
  try {
    return JSON.parse(text) as Record<string, unknown>
  } catch {
    throw new Error('Eligibility service returned invalid JSON.')
  }
}

function pickString(obj: Record<string, unknown>, keys: string[]): string {
  for (const k of keys) {
    const v = obj[k]
    if (v != null && String(v).trim() !== '') return String(v).trim()
  }
  return ''
}

function normalizePayerRow(raw: unknown): PverifyPayerRow | null {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null
  const o = raw as Record<string, unknown>
  const payerCode = pickString(o, ['PverifyPayerCode', 'PayerCode', 'payerCode', 'Code'])
  const payerName = pickString(o, ['PayerName', 'PayorName', 'payerName', 'Name'])
  if (!payerCode || !payerName) return null
  return { payerName, payerCode }
}

function extractPayerArray(data: unknown): unknown[] {
  if (Array.isArray(data)) return data
  if (!data || typeof data !== 'object') return []
  const obj = data as Record<string, unknown>
  for (const key of ['Payers', 'payers', 'Data', 'data', 'Result', 'result']) {
    if (Array.isArray(obj[key])) return obj[key] as unknown[]
  }
  return []
}

type SettingsPverifyConfig = {
  clientKey: string
  clientSecret: string
  clientApiId: string
  clientUserName: string
  apiUrl: string
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' ? (value as Record<string, unknown>) : {}
}

function readString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : ''
}

function pickObject(source: Record<string, unknown>, keys: string[]): Record<string, unknown> {
  for (const key of keys) {
    const value = source[key]
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value as Record<string, unknown>
    }
  }
  return {}
}

function resolveSettingsPverifyConfig(data: unknown): SettingsPverifyConfig {
  const payload = asRecord(data)
  const eligibilityData = pickObject(payload, ['eligibility', 'eligibilityService', 'eligibility_service'])
  const pverifyData = pickObject(eligibilityData, ['pverify', 'pverifyConfig', 'pverify_config'])

  return {
    clientKey: readString(pverifyData.clientKey ?? pverifyData.client_key),
    clientSecret: readString(pverifyData.clientSecret ?? pverifyData.client_secret),
    clientApiId: readString(pverifyData.clientApiId ?? pverifyData.client_api_id),
    clientUserName: readString(pverifyData.clientUserName ?? pverifyData.client_user_name),
    apiUrl: readString(pverifyData.apiUrl ?? pverifyData.api_url),
  }
}

async function parseApiResponseBody(res: Response): Promise<unknown> {
  const text = await res.text()
  if (!text) return null
  try {
    return JSON.parse(text) as unknown
  } catch {
    throw new Error(`Request failed (${res.status})`)
  }
}

function readApiMessage(body: unknown, fallback: string): string {
  if (!body || typeof body !== 'object') return fallback
  const record = body as Record<string, unknown>
  for (const field of ['message', 'msg', 'error', 'detail']) {
    const value = record[field]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return fallback
}

function extractDataField(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body
  const record = body as Record<string, unknown>
  return 'data' in record ? record.data : body
}

async function requestPverifyPayers(headers?: HeadersInit): Promise<unknown> {
  const res = await apiRequest('/integrations/pverify/payers', {
    method: 'GET',
    headers,
  })
  const body = await parseApiResponseBody(res)
  if (!res.ok) {
    throw new Error(readApiMessage(body, `Request failed (${res.status})`))
  }
  return extractDataField(body)
}

export async function fetchPverifyPayers(_config: PverifyServiceConfig): Promise<PverifyPayerRow[]> {
  let parsed: unknown
  try {
    parsed = await requestPverifyPayers()
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unable to load pVerify payers.'
    if (!/PVERIFY_CLIENT_ID and PVERIFY_CLIENT_SECRET must be set/i.test(message)) {
      throw error
    }

    const settings = await getSettingsFull()
    const pverify = resolveSettingsPverifyConfig(settings.data ?? settings)
    if (!pverify.clientKey || !pverify.clientSecret) {
      throw new Error('pVerify client key and secret are missing in Settings.')
    }

    parsed = await requestPverifyPayers({
      'X-PVerify-Client-Id': pverify.clientKey,
      'X-PVerify-Client-Secret': pverify.clientSecret,
      ...(pverify.clientApiId ? { 'X-PVerify-Client-Api-Id': pverify.clientApiId } : {}),
      ...(pverify.clientUserName ? { 'X-PVerify-Client-User-Name': pverify.clientUserName } : {}),
      ...(pverify.apiUrl ? { 'X-PVerify-Api-Url': pverify.apiUrl } : {}),
    })
  }

  const rows = extractPayerArray(parsed)
    .map(normalizePayerRow)
    .filter((row): row is PverifyPayerRow => row !== null)
  rows.sort((a, b) => a.payerName.localeCompare(b.payerName, undefined, { sensitivity: 'base' }))
  return rows
}
