import { useMemo, useState, type ReactNode } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { ROUTES, PATIENT_NAV } from '../routes/routeMap'
import {
  Download,
  Mail,
  AlertTriangle,
  Loader2,
  CheckCircle2,
  Shield,
  BadgeCheck,
  ArrowLeft,
  DollarSign,
  Package,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import Toast from '../components/Toast'
import Button from '../components/forms/Button'
import Timeline from '../components/Timeline'
import StediEligibilityResultPanel from '../components/StediEligibilityResultPanel'
import { PatientFlowCogniThemeScope, useTheme } from '../contexts/ThemeContext'
import { useEligibilityServiceConfig } from '../contexts/EligibilityServiceContext'
import type { EligibilityResultRouteState } from '../services/mapPverifyToEligibilityView'
import { fetchEligibilityPdfReport } from '../services/pverifyAuth'
import { fetchStediEligibilityPdfReport } from '../services/stediService'
import { buildEligibilityDashboardView } from '../services/eligibilityDashboardView'

type ThemeColors = {
  background: string
  cardBackground: string
  cardBorder: string
  border: string
  textPrimary: string
  textSecondary: string
  primary: string
  navHeaderBackground: string
}

type VerifyFieldCard = {
  key: string
  label: string
  value: string
  confidence?: number
  polygon?: number[]
}

const cardShadow = (isDark: boolean) =>
  isDark
    ? '0 24px 48px -16px rgba(0, 0, 0, 0.45)'
    : '0 20px 50px -12px rgba(15, 23, 42, 0.08)'

function fmtUsd(n: number) {
  return `$${n.toFixed(2)}`
}

/** Matches Patient Intake: full-width strip with themed header background. */
function FlowPageHeader({
  colors,
  logo,
  title,
  description,
  Icon,
  actions,
}: {
  colors: {
    border: string
    cardBackground: string
    textPrimary: string
    textSecondary: string
    primary: string
    navHeaderBackground: string
  }
  logo?: string
  title: string
  description: string
  Icon: LucideIcon
  actions?: ReactNode
}) {
  return (
    <header
      className="relative z-[1] w-full border-b"
      style={{
        borderColor: colors.border,
        backgroundColor: colors.navHeaderBackground,
      }}
    >
      <div className="w-full px-4 py-3 sm:px-6 sm:py-3.5">
        <div className="flex flex-col gap-2 lg:flex-row lg:items-center lg:justify-between lg:gap-4">
          <div className="flex min-w-0 flex-1 flex-col gap-2 sm:flex-row sm:items-center sm:gap-3">
            {logo ? (
              <img
                src={logo}
                alt="Health Lynk"
                className="h-6 w-auto max-w-[min(100%,200px)] shrink-0 object-contain object-left sm:h-7"
              />
            ) : (
              <p
                className="shrink-0 text-base font-bold leading-none tracking-tight sm:text-lg"
                style={{ color: colors.primary }}
              >
                Health Lynk
              </p>
            )}
            <div className="flex min-w-0 flex-1 items-center gap-2.5 sm:gap-3">
              <span
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg sm:h-9 sm:w-9"
                style={{
                  backgroundColor: `color-mix(in srgb, ${colors.primary} 18%, transparent)`,
                  color: colors.primary,
                  boxShadow: `0 0 0 1px color-mix(in srgb, ${colors.primary} 35%, transparent)`,
                }}
              >
                <Icon className="h-4 w-4 sm:h-[18px] sm:w-[18px]" aria-hidden />
              </span>
              <div className="min-w-0 flex-1">
                <h1
                  className="text-lg font-semibold leading-tight tracking-tight sm:text-xl"
                  style={{ color: colors.textPrimary }}
                >
                  {title}
                </h1>
                <p
                  className="mt-0.5 max-w-2xl text-xs leading-snug sm:text-sm"
                  style={{ color: colors.textSecondary }}
                >
                  {description}
                </p>
              </div>
            </div>
          </div>
          {actions ? (
            <div className="flex w-full shrink-0 flex-col gap-2 sm:flex-row sm:flex-wrap sm:justify-end lg:w-auto lg:max-w-[min(100%,28rem)] xl:max-w-none">
              {actions}
            </div>
          ) : null}
        </div>
      </div>
    </header>
  )
}

function EligibilityResultContent({ providerMode = false }: { providerMode?: boolean }) {
  const { theme } = useTheme()
  const isDarkMode = true
  const location = useLocation()
  const navigate = useNavigate()
  const { selectedService, serviceConfigs } = useEligibilityServiceConfig()
  const state = location.state as EligibilityResultRouteState | null
  const [pdfLoading, setPdfLoading] = useState(false)
  const [showToast, setShowToast] = useState(false)
  const [toastMessage, setToastMessage] = useState('')
  const [toastType, setToastType] = useState<'success' | 'error' | 'info'>(
    'error'
  )

  const tc: ThemeColors = {
    background: theme.colors.background,
    cardBackground: theme.colors.cardBackground,
    cardBorder: theme.colors.cardBorder,
    border: theme.colors.border,
    textPrimary: theme.colors.textPrimary,
    textSecondary: theme.colors.textSecondary,
    primary: theme.colors.primary,
    navHeaderBackground: theme.colors.navHeaderBackground,
  }

  const surfaceCard = {
    backgroundColor: tc.cardBackground,
    border: `1px solid ${tc.cardBorder}`,
    boxShadow: isDarkMode
      ? `0 0 0 1px color-mix(in srgb, ${tc.primary} 14%, transparent), 0 24px 48px -16px rgba(0, 0, 0, 0.5), 0 0 72px -28px color-mix(in srgb, ${tc.primary} 22%, transparent)`
      : cardShadow(isDarkMode),
  } as const

  const layoutBackdropStyle = {
    backgroundColor: tc.background,
    backgroundImage: isDarkMode
      ? `
        radial-gradient(ellipse 120% 80% at 50% -8%, color-mix(in srgb, ${tc.primary} 42%, transparent) 0%, transparent 50%),
        radial-gradient(ellipse 70% 55% at 0% 32%, color-mix(in srgb, ${tc.primary} 26%, transparent) 0%, transparent 58%),
        radial-gradient(ellipse 65% 52% at 100% 52%, color-mix(in srgb, ${tc.primary} 22%, transparent) 0%, transparent 58%),
        radial-gradient(ellipse 90% 60% at 50% 102%, color-mix(in srgb, ${tc.primary} 16%, transparent) 0%, transparent 55%),
        linear-gradient(180deg,
          color-mix(in srgb, ${tc.primary} 12%, ${tc.background}) 0%,
          ${tc.background} 40%,
          color-mix(in srgb, ${tc.primary} 10%, ${tc.background}) 100%)`
      : `
        radial-gradient(ellipse 115% 72% at 50% -4%, color-mix(in srgb, ${tc.primary} 20%, transparent) 0%, transparent 54%),
        radial-gradient(ellipse 68% 52% at 0% 38%, color-mix(in srgb, ${tc.primary} 12%, transparent) 0%, transparent 58%),
        radial-gradient(ellipse 62% 50% at 100% 58%, color-mix(in srgb, ${tc.primary} 10%, transparent) 0%, transparent 56%),
        radial-gradient(ellipse 85% 58% at 50% 102%, color-mix(in srgb, ${tc.primary} 8%, transparent) 0%, transparent 54%),
        linear-gradient(180deg,
          color-mix(in srgb, ${tc.primary} 6%, ${tc.cardBackground}) 0%,
          ${tc.background} 45%,
          color-mix(in srgb, ${tc.primary} 5%, ${tc.background}) 100%)`,
  } as const

  const pushToast = (
    message: string,
    type: 'success' | 'error' | 'info' = 'error'
  ) => {
    setToastMessage(message)
    setToastType(type)
    setShowToast(true)
  }

  const raw = state?.rawResponse ?? null
  const sourceService = (state?.apiMeta?.source ?? selectedService) as
    | 'stedi'
    | 'pverify'
    | 'azure-health-card'
  const ic = state?.intakeContext
  const clickAndVerifyFields = state?.apiMeta?.clickAndVerifyFields
  const [selectedVerifyFieldKey, setSelectedVerifyFieldKey] = useState<string | null>(null)

  const verifyFields = useMemo<VerifyFieldCard[]>(() => {
    if (!clickAndVerifyFields) return []
    const rows = Object.entries(clickAndVerifyFields).map(([key, field]) => ({
      key,
      label: field.label,
      value: field.value,
      confidence: field.confidence,
      polygon: field.polygon,
    }))
    rows.sort((a, b) => {
      const aConf = a.confidence ?? -1
      const bConf = b.confidence ?? -1
      return bConf - aConf
    })
    return rows
  }, [clickAndVerifyFields])

  const selectedVerifyField = useMemo(() => {
    if (verifyFields.length === 0) return null
    if (!selectedVerifyFieldKey) return verifyFields[0]
    return verifyFields.find((f) => f.key === selectedVerifyFieldKey) ?? verifyFields[0]
  }, [verifyFields, selectedVerifyFieldKey])

  const dashboard = useMemo(() => {
    if (!raw) return null
    return buildEligibilityDashboardView(raw, {
      patientName: ic?.patientName ?? '',
      cptHcpcCode: ic?.cptHcpcCode ?? '',
      serviceDateFrom: ic?.serviceDateFrom ?? '',
      serviceDateTo: ic?.serviceDateTo ?? '',
    })
  }, [
    raw,
    ic?.patientName,
    ic?.cptHcpcCode,
    ic?.serviceDateFrom,
    ic?.serviceDateTo,
  ])

  const handleDownloadPDF = async () => {
    setPdfLoading(true)
    try {
      if (!raw) {
        throw new Error('No eligibility response found for PDF download.')
      }
      let blob: Blob
      let fileName: string
      if (sourceService === 'stedi') {
        const stediRaw: Record<string, unknown> =
          raw.StediRawResponse &&
          typeof raw.StediRawResponse === 'object' &&
          !Array.isArray(raw.StediRawResponse)
            ? (raw.StediRawResponse as Record<string, unknown>)
            : raw
        const eligibilitySearchId =
          stediRaw.eligibilitySearchId != null
            ? String(stediRaw.eligibilitySearchId)
            : undefined
        blob = await fetchStediEligibilityPdfReport({
          eligibilityCheckId: eligibilitySearchId,
          apiKey: serviceConfigs.stedi.apiKey,
        })
        fileName = `stedi-eligibility-${eligibilitySearchId ?? Date.now()}.pdf`
      } else {
        const rid =
          state?.apiMeta?.requestId ??
          (typeof state?.rawResponse?.RequestID === 'number'
            ? state.rawResponse.RequestID
            : undefined)
        if (rid == null) {
          throw new Error('No pVerify Request ID found for PDF download.')
        }
        blob = await fetchEligibilityPdfReport(rid)
        fileName = `eligibility-${rid}.pdf`
      }
      const href = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = href
      a.download = fileName
      document.body.appendChild(a)
      a.click()
      a.remove()
      URL.revokeObjectURL(href)
      pushToast('PDF downloaded successfully.', 'success')
    } catch (e) {
      pushToast(
        e instanceof Error ? e.message : 'PDF download failed.',
        'error'
      )
    } finally {
      setPdfLoading(false)
    }
  }

  const handleSendToEmail = () => {
    pushToast('Send to email will be available in a future update.', 'info')
  }

  const handleBackToIntake = () => {
    if (providerMode) {
      navigate(ROUTES.PROVIDER_PATIENT_INTAKE)
      return
    }
    navigate(ROUTES.PATIENT_HOME, { state: PATIENT_NAV.intake })
  }

  const toastEl = (
    <Toast
      message={toastMessage}
      type={toastType}
      isVisible={showToast}
      onClose={() => setShowToast(false)}
      duration={toastType === 'error' ? 6000 : toastType === 'info' ? 4000 : 3000}
    />
  )

  if (!raw || !dashboard) {
    return (
      <>
        <div className="relative min-h-screen">
          {!providerMode && (
            <>
              <div
                className="pointer-events-none absolute inset-0 min-h-full"
                style={layoutBackdropStyle}
                aria-hidden
              />
              <FlowPageHeader
                colors={tc}
                logo={theme.logo}
                title="Eligibility result"
                description={`Review coverage and benefits returned by ${sourceService === 'stedi' ? 'Stedi' : 'pVerify'}.`}
                Icon={BadgeCheck}
                actions={
                  <Button
                    variant="outline"
                    size="lg"
                    type="button"
                    onClick={handleBackToIntake}
                    className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-5 sm:w-auto"
                  >
                    <ArrowLeft className="h-[18px] w-[18px] shrink-0" aria-hidden />
                    <span>Back to Service</span>
                  </Button>
                }
              />
            </>
          )}
          <div className="relative z-10 flex min-h-[45vh] w-full items-center justify-center px-4 py-12 sm:px-6">
            <div
              className="w-full max-w-md rounded-2xl p-8 text-center"
              style={surfaceCard}
            >
              <h2
                className="text-xl font-bold tracking-tight sm:text-2xl"
                style={{ color: tc.textPrimary }}
              >
                No eligibility response yet
              </h2>
              <p className="mb-8 mt-3 text-sm leading-relaxed" style={{ color: tc.textSecondary }}>
                Run a check from Patient Intake. Results will appear here after the selected service returns.
              </p>
              <Button
                variant="primary"
                size="lg"
                onClick={() =>
                  providerMode
                    ? navigate(ROUTES.PROVIDER_PATIENT_INTAKE, { replace: true })
                    : navigate(ROUTES.PATIENT_HOME, { replace: true, state: PATIENT_NAV.intake })
                }
              >
                Go to Patient Intake
              </Button>
            </div>
          </div>
        </div>
        {toastEl}
      </>
    )
  }

  const apiOk = String(raw.APIResponseCode ?? '') === '0'
  const processedErr = raw.ProcessedWithError === true

  const requestId =
    state?.apiMeta?.requestId ??
    (typeof raw.RequestID === 'number' ? raw.RequestID : undefined)

  const d = dashboard

  const canDownloadPdf =
    sourceService === 'pverify'
      ? requestId != null
      : Boolean(
          raw &&
            ((raw.StediRawResponse &&
              typeof raw.StediRawResponse === 'object' &&
              !Array.isArray(raw.StediRawResponse) &&
              (raw.StediRawResponse as Record<string, unknown>).eligibilitySearchId != null) ||
              raw.eligibilitySearchId != null)
        )

  const headerActions = (
    <>
      <Button
        variant="outline"
        size="lg"
        type="button"
        onClick={handleSendToEmail}
        className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-4 sm:w-auto"
      >
        <Mail className="h-[18px] w-[18px] shrink-0" aria-hidden />
        <span>Send to Email</span>
      </Button>
      <Button
        variant="primary"
        size="lg"
        type="button"
        onClick={() => void handleDownloadPDF()}
        disabled={pdfLoading || !canDownloadPdf}
        className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-4 sm:w-auto"
      >
        {pdfLoading ? (
          <>
            <Loader2 className="h-[18px] w-[18px] shrink-0 animate-spin" aria-hidden />
            <span>Downloading…</span>
          </>
        ) : (
          <>
            <Download className="h-[18px] w-[18px] shrink-0" aria-hidden />
            <span>Download PDF</span>
          </>
        )}
      </Button>
      <Button
        variant="outline"
        size="lg"
        type="button"
        onClick={handleBackToIntake}
        className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-4 sm:w-auto"
      >
        <ArrowLeft className="h-[18px] w-[18px] shrink-0" aria-hidden />
        <span>Back to Service</span>
      </Button>
    </>
  )
  const providerActions = (
    <>
      <Button
        variant="outline"
        size="lg"
        type="button"
        onClick={handleSendToEmail}
        className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-4 sm:w-auto"
      >
        <Mail className="h-[18px] w-[18px] shrink-0" aria-hidden />
        <span>Send to Email</span>
      </Button>
      <Button
        variant="primary"
        size="lg"
        type="button"
        onClick={() => void handleDownloadPDF()}
        disabled={pdfLoading || !canDownloadPdf}
        className="inline-flex min-h-[44px] w-full items-center justify-center gap-2 px-4 sm:w-auto"
      >
        {pdfLoading ? (
          <>
            <Loader2 className="h-[18px] w-[18px] shrink-0 animate-spin" aria-hidden />
            <span>Downloading…</span>
          </>
        ) : (
          <>
            <Download className="h-[18px] w-[18px] shrink-0" aria-hidden />
            <span>Download PDF</span>
          </>
        )}
      </Button>
    </>
  )

  return (
    <div className="relative min-h-screen">
      {!providerMode && (
        <>
          <div
            className="pointer-events-none absolute inset-0 min-h-full"
            style={layoutBackdropStyle}
            aria-hidden
          />
          <FlowPageHeader
            colors={tc}
            logo={theme.logo}
            title="Eligibility result"
            description={`Verification summary for ${d.patientName || 'patient'}. Review coverage, costs, and authorization below.`}
            Icon={BadgeCheck}
            actions={headerActions}
          />
        </>
      )}

      <div className="relative z-10 w-full space-y-6 px-4 py-6 sm:space-y-8 sm:px-6 sm:py-8">
        {providerMode && (
          <div className="flex flex-col gap-3 sm:gap-4">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <h1
                  className="text-xl sm:text-2xl font-bold text-left"
                  style={{ color: tc.textPrimary }}
                >
                  Eligibility Result
                </h1>
                <p
                  className="mt-1 text-left"
                  style={{ color: tc.textSecondary }}
                >
                  Review coverage, costs, and authorization details from the eligibility response.
                </p>
              </div>
              <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap sm:justify-end sm:self-start">
                {providerActions}
              </div>
            </div>
          </div>
        )}

        {(processedErr || !apiOk) && (
          <div
            className="flex items-start gap-3 rounded-2xl border px-4 py-4 text-sm sm:px-5 sm:text-[15px]"
            style={{
              backgroundColor: 'color-mix(in srgb, #f87171 12%, transparent)',
              borderColor: 'color-mix(in srgb, #f87171 35%, transparent)',
              color: tc.textPrimary,
            }}
          >
            <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-red-600" />
            <div>
              <p className="text-base font-semibold">Response needs review</p>
              <p className="mt-1.5 leading-relaxed opacity-95">
                This result may be incomplete or returned an error from the payer.
                {raw.ErrorDescription != null &&
                  String(raw.ErrorDescription).trim() !== '' && (
                    <span className="mt-2 block font-medium">
                      {String(raw.ErrorDescription)}
                    </span>
                  )}
              </p>
            </div>
          </div>
        )}

        {/* Summary hero — key outcome at a glance */}
        <section
          className="relative overflow-hidden rounded-2xl border-2 p-6 sm:p-8 lg:p-10"
          style={{
            ...surfaceCard,
            borderColor: tc.primary,
            background: `linear-gradient(135deg, color-mix(in srgb, ${tc.primary} 12%, ${tc.cardBackground}) 0%, ${tc.cardBackground} 60%)`,
          }}
        >
          <div className="flex flex-col gap-8 lg:flex-row lg:items-start lg:justify-between">
            <div className="min-w-0 flex-1 space-y-3">
              <p
                className="text-xs font-semibold uppercase tracking-wider"
                style={{ color: tc.textSecondary }}
              >
                Patient
              </p>
              <p
                className="break-words text-3xl font-bold tracking-tight sm:text-4xl lg:text-5xl"
                style={{ color: tc.textPrimary }}
              >
                {d.patientName || '—'}
              </p>
              <p className="text-base sm:text-lg" style={{ color: tc.textSecondary }}>
                <span className="font-semibold" style={{ color: tc.textPrimary }}>
                  {d.payor || '—'}
                </span>
                {d.planName ? <span> · {d.planName}</span> : null}
              </p>
              <div className="flex flex-wrap gap-2 pt-2 sm:gap-3">
                <span
                  className="rounded-xl px-3 py-2 text-sm font-semibold sm:text-base"
                  style={{
                    backgroundColor: `color-mix(in srgb, ${tc.primary} 14%, transparent)`,
                    color: tc.textPrimary,
                  }}
                >
                  Code {d.serviceCode || '—'}
                </span>
                <span
                  className="rounded-xl px-3 py-2 text-sm font-semibold sm:text-base"
                  style={{
                    backgroundColor: `color-mix(in srgb, ${tc.primary} 14%, transparent)`,
                    color: tc.textPrimary,
                  }}
                >
                  Service {d.serviceDate || '—'}
                </span>
              </div>
            </div>
            <div className="flex shrink-0 flex-col items-start gap-3 lg:items-end">
              {d.statusEligible ? (
                <span className="inline-flex items-center gap-2 rounded-full bg-emerald-100 px-4 py-2.5 text-base font-bold text-emerald-900 sm:text-lg">
                  <CheckCircle2 className="h-6 w-6 shrink-0" aria-hidden />
                  Eligible
                </span>
              ) : (
                <span className="inline-flex items-center gap-2 rounded-full bg-amber-100 px-4 py-2.5 text-base font-bold text-amber-950 sm:text-lg">
                  <AlertTriangle className="h-6 w-6 shrink-0" aria-hidden />
                  Review required
                </span>
              )}
              <p
                className="max-w-xs text-right text-sm font-medium leading-snug sm:text-base"
                style={{ color: tc.textSecondary }}
              >
                Coverage {d.coverageActive ? 'active' : 'needs review'} ·{' '}
                {d.networkInNetwork ? 'In-network' : 'Out-of-network'}
              </p>
            </div>
          </div>
        </section>

        {sourceService === 'stedi' ? (
          <StediEligibilityResultPanel
            raw={
              raw.StediRawResponse &&
              typeof raw.StediRawResponse === 'object' &&
              !Array.isArray(raw.StediRawResponse)
                ? (raw.StediRawResponse as Record<string, unknown>)
                : raw
            }
            colors={tc}
            surfaceCard={surfaceCard}
          />
        ) : (
          <>
        {/* Coverage Information */}
        <section className="rounded-2xl p-5 sm:p-8" style={surfaceCard}>
          <h2
            className="mb-4 text-base font-semibold tracking-tight sm:mb-5 sm:text-lg"
            style={{ color: tc.textPrimary }}
          >
            Coverage details
          </h2>
          <dl className="grid grid-cols-1 gap-x-8 gap-y-4 sm:grid-cols-2 sm:gap-y-5">
            {[
              { label: 'Patient Name', value: d.patientName },
              { label: 'Patient ID', value: d.patientId },
              { label: 'Payor', value: d.payor },
              { label: 'Plan', value: d.planName },
              { label: 'Service Code', value: d.serviceCode },
              { label: 'Service Date', value: d.serviceDate },
              {
                label: 'Coverage Status',
                value: (
                  <span
                    className={`inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${
                      d.coverageActive
                        ? 'bg-emerald-100 text-emerald-800'
                        : 'bg-amber-100 text-amber-900'
                    }`}
                  >
                    {d.coverageActive ? 'Active' : 'Review'}
                  </span>
                ),
              },
              { label: 'Plan Type', value: d.planType },
              {
                label: 'Network Status',
                value: (
                  <span
                    className={`inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${
                      d.networkInNetwork
                        ? 'bg-emerald-100 text-emerald-800'
                        : 'bg-amber-100 text-amber-900'
                    }`}
                  >
                    {d.networkInNetwork ? 'In-Network' : 'Out-of-network'}
                  </span>
                ),
              },
              { label: 'Effective Date', value: d.effectiveDateDisplay },
            ].map((row) => (
              <div key={row.label} className="min-w-0">
                <dt
                  className="mb-1 text-[11px] font-semibold uppercase tracking-wide sm:text-xs"
                  style={{ color: tc.textSecondary }}
                >
                  {row.label}
                </dt>
                <dd
                  className="break-words text-sm font-medium leading-snug sm:text-base"
                  style={{ color: tc.textPrimary }}
                >
                  {row.value}
                </dd>
              </div>
            ))}
          </dl>
        </section>

        {/* DME — pVerify DMESummary */}
        <section className="rounded-xl p-5 sm:p-8" style={surfaceCard}>
          <div className="mb-4 flex flex-col gap-3 sm:mb-5 sm:flex-row sm:items-start sm:gap-4">
            <span
              className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl"
              style={{
                backgroundColor: `color-mix(in srgb, ${tc.primary} 14%, transparent)`,
                color: tc.primary,
              }}
            >
              <Package className="h-5 w-5" aria-hidden />
            </span>
            <div className="min-w-0 flex-1">
              <h2
                className="text-base font-semibold tracking-tight sm:text-lg"
                style={{ color: tc.textPrimary }}
              >
                Durable medical equipment (DME)
              </h2>
              <p
                className="mt-1 text-sm leading-snug"
                style={{ color: tc.textSecondary }}
              >
                Fields from the payer&apos;s DME summary when returned with this
                eligibility check.
              </p>
            </div>
          </div>
          {!d.dme.sourcePresent ? (
            <p className="text-sm leading-relaxed" style={{ color: tc.textSecondary }}>
              No DME summary block was included in this response.
            </p>
          ) : d.dme.rows.length === 0 ? (
            <p className="text-sm leading-relaxed" style={{ color: tc.textSecondary }}>
              DME summary was present but contained no displayable values.
            </p>
          ) : (
            <dl className="grid grid-cols-1 gap-x-8 gap-y-4 sm:grid-cols-2 sm:gap-y-5">
              {d.dme.rows.map((row, i) => (
                <div key={`${row.label}-${i}`} className="min-w-0">
                  <dt
                    className="mb-1 text-[11px] font-semibold uppercase tracking-wide sm:text-xs"
                    style={{ color: tc.textSecondary }}
                  >
                    {row.label}
                  </dt>
                  <dd
                    className="break-words text-sm font-medium leading-snug sm:text-base"
                    style={{ color: tc.textPrimary }}
                  >
                    {row.value}
                  </dd>
                </div>
              ))}
            </dl>
          )}
        </section>

        {/* Click-and-verify (Azure card extraction source map) */}
        {verifyFields.length > 0 && (
          <section className="rounded-2xl p-5 sm:p-8" style={surfaceCard}>
            <div className="mb-5 sm:mb-6">
              <h2
                className="text-base font-semibold tracking-tight sm:text-lg"
                style={{ color: tc.textPrimary }}
              >
                Verify extracted fields
              </h2>
              <p
                className="mt-1 text-sm leading-snug"
                style={{ color: tc.textSecondary }}
              >
                Review OCR output from the insurance card. Polygon coordinates are included
                for click-and-verify overlays.
              </p>
            </div>

            <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
              <div className="space-y-2">
                {verifyFields.map((field) => {
                  const isSelected = selectedVerifyField?.key === field.key
                  const confidencePct =
                    typeof field.confidence === 'number'
                      ? `${Math.round(field.confidence * 100)}%`
                      : '—'
                  return (
                    <button
                      key={field.key}
                      type="button"
                      onClick={() => setSelectedVerifyFieldKey(field.key)}
                      className="w-full rounded-xl border px-3 py-3 text-left transition-colors sm:px-4"
                      style={{
                        borderColor: isSelected
                          ? tc.primary
                          : 'color-mix(in srgb, #64748b 30%, transparent)',
                        backgroundColor: isSelected
                          ? `color-mix(in srgb, ${tc.primary} 12%, transparent)`
                          : 'transparent',
                      }}
                    >
                      <p
                        className="text-[11px] font-semibold uppercase tracking-wide sm:text-xs"
                        style={{ color: tc.textSecondary }}
                      >
                        {field.label}
                      </p>
                      <p
                        className="mt-1 break-words text-sm font-medium leading-snug sm:text-base"
                        style={{ color: tc.textPrimary }}
                      >
                        {field.value}
                      </p>
                      <p className="mt-1 text-xs" style={{ color: tc.textSecondary }}>
                        Confidence: {confidencePct}
                      </p>
                    </button>
                  )
                })}
              </div>

              <div
                className="rounded-xl border p-4 sm:p-5"
                style={{
                  borderColor: 'color-mix(in srgb, #64748b 30%, transparent)',
                  backgroundColor: 'color-mix(in srgb, #64748b 8%, transparent)',
                }}
              >
                <p
                  className="text-[11px] font-semibold uppercase tracking-wide sm:text-xs"
                  style={{ color: tc.textSecondary }}
                >
                  Selected field
                </p>
                <p
                  className="mt-1 text-base font-semibold sm:text-lg"
                  style={{ color: tc.textPrimary }}
                >
                  {selectedVerifyField?.label ?? '—'}
                </p>
                <p
                  className="mt-1 break-words text-sm sm:text-base"
                  style={{ color: tc.textPrimary }}
                >
                  {selectedVerifyField?.value ?? '—'}
                </p>
                <p className="mt-2 text-xs" style={{ color: tc.textSecondary }}>
                  Confidence:{' '}
                  {typeof selectedVerifyField?.confidence === 'number'
                    ? `${Math.round(selectedVerifyField.confidence * 100)}%`
                    : '—'}
                </p>
                <div className="mt-3">
                  <p
                    className="text-[11px] font-semibold uppercase tracking-wide sm:text-xs"
                    style={{ color: tc.textSecondary }}
                  >
                    Polygon (x,y points)
                  </p>
                  <p
                    className="mt-1 break-all font-mono text-xs leading-relaxed"
                    style={{ color: tc.textPrimary }}
                  >
                    {selectedVerifyField?.polygon?.length
                      ? selectedVerifyField.polygon.join(', ')
                      : 'No polygon returned for this field.'}
                  </p>
                </div>
              </div>
            </div>
          </section>
        )}

        {/* Financial Information — single card, stat row (reference: compact columns + remaining lines) */}
        <section className="rounded-2xl p-5 sm:p-6 lg:p-8" style={surfaceCard}>
          <div className="mb-6 flex items-center gap-2.5 sm:mb-8">
            <DollarSign
              className="h-5 w-5 shrink-0 sm:h-[22px] sm:w-[22px]"
              style={{ color: tc.primary }}
              aria-hidden
            />
            <h2
              className="text-lg font-bold tracking-tight sm:text-xl"
              style={{ color: tc.textPrimary }}
            >
              Financial Information
            </h2>
          </div>
          <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 sm:gap-x-8 sm:gap-y-8 lg:grid-cols-4 lg:gap-0 lg:divide-x lg:divide-gray-200 dark:lg:divide-gray-700">
            {[
              {
                label: 'Copay',
                main: fmtUsd(d.financial.copay),
                sub:
                  d.financial.copayRemaining > 0
                    ? `${fmtUsd(d.financial.copayRemaining)} remaining`
                    : null,
              },
              {
                label: 'Deductible',
                main: fmtUsd(d.financial.deductible),
                sub:
                  d.financial.deductible > 0
                    ? `${fmtUsd(d.financial.deductibleRemaining)} remaining`
                    : null,
              },
              {
                label: 'Out of Pocket Maximum',
                main: fmtUsd(d.financial.outOfPocketMax),
                sub:
                  d.financial.outOfPocketMax > 0
                    ? `${fmtUsd(d.financial.outOfPocketRemaining)} remaining`
                    : null,
              },
              {
                label: 'Coinsurance',
                main: d.financial.coinsurance,
                sub: d.financial.coinsuranceSubline ?? null,
              },
            ].map((cell, idx) => (
              <div
                key={cell.label}
                className={`min-w-0 text-left lg:px-6 ${idx === 0 ? 'lg:pl-0' : ''} ${idx === 3 ? 'lg:pr-0' : ''}`}
              >
                <p
                  className="text-xs font-normal leading-tight sm:text-sm"
                  style={{ color: tc.textSecondary }}
                >
                  {cell.label}
                </p>
                <p
                  className="mt-2 text-2xl font-bold tabular-nums tracking-tight sm:text-3xl"
                  style={{ color: tc.textPrimary }}
                >
                  {cell.main}
                </p>
                {cell.sub && (
                  <p
                    className="mt-1.5 text-xs font-normal tabular-nums leading-snug sm:text-sm"
                    style={{ color: tc.textSecondary }}
                  >
                    {cell.sub}
                  </p>
                )}
              </div>
            ))}
          </div>
        </section>

      {/* Alert banners */}
      {d.warnings.length > 0 && (
        <div className="space-y-3">
          {d.warnings.map((w, i) => (
            <div
              key={i}
              className={`flex items-start gap-3 rounded-lg border px-4 py-3 text-sm ${
                w.severity === 'high'
                  ? 'bg-red-50 border-red-200 text-red-900 dark:bg-red-950/40 dark:border-red-800 dark:text-red-100'
                  : 'bg-amber-50 border-amber-200 text-amber-950 dark:bg-amber-950/30 dark:border-amber-800 dark:text-amber-100'
              }`}
            >
              <AlertTriangle
                className={`w-5 h-5 shrink-0 mt-0.5 ${
                  w.severity === 'high' ? 'text-red-600' : 'text-amber-600'
                }`}
              />
              <p className="leading-snug">{w.message}</p>
            </div>
          ))}
        </div>
      )}

      {/* Benefits summary — authorization */}
      <section className="rounded-2xl p-5 sm:p-8" style={surfaceCard}>
        <div className="mb-6 flex items-center gap-3 sm:mb-8">
          <span
            className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl"
            style={{
              backgroundColor: `color-mix(in srgb, ${tc.primary} 14%, transparent)`,
              color: tc.primary,
            }}
          >
            <Shield className="h-5 w-5" aria-hidden />
          </span>
          <h2
            className="text-xl font-bold tracking-tight sm:text-2xl"
            style={{ color: tc.textPrimary }}
          >
            Authorization status
          </h2>
        </div>
        <div className="space-y-6 text-base">
          <div className="flex flex-wrap items-center gap-3">
            <span className="font-medium" style={{ color: tc.textSecondary }}>
              Authorization required:
            </span>
            {d.authorization.required ? (
              <span className="inline-flex rounded-full bg-amber-100 px-3 py-1 text-sm font-bold text-amber-950">
                {d.authorization.status === 'pending' ? 'Pending' : 'Yes'}
              </span>
            ) : (
              <span className="inline-flex rounded-full bg-emerald-100 px-3 py-1 text-sm font-bold text-emerald-900">
                Not required
              </span>
            )}
          </div>
          <dl className="grid grid-cols-1 gap-6 sm:grid-cols-2 sm:gap-8">
            <div>
              <dt
                className="mb-1.5 text-xs font-semibold uppercase tracking-wide"
                style={{ color: tc.textSecondary }}
              >
                Prior authorization number
              </dt>
              <dd
                className="text-lg font-semibold sm:text-xl"
                style={{ color: tc.textPrimary }}
              >
                {d.authorization.priorAuthNumber ?? '—'}
              </dd>
            </div>
            <div>
              <dt
                className="mb-1.5 text-xs font-semibold uppercase tracking-wide"
                style={{ color: tc.textSecondary }}
              >
                Submitted date
              </dt>
              <dd
                className="text-lg font-semibold sm:text-xl"
                style={{ color: tc.textPrimary }}
              >
                {d.authorization.submittedDate ?? '—'}
              </dd>
            </div>
          </dl>
        </div>
      </section>

      {/* Timeline — strip uses header purple (#1f1139 via navHeaderBackground) */}
      <section
        className="rounded-xl p-5 sm:p-8"
        style={{
          ...surfaceCard,
          backgroundColor: theme.colors.navHeaderBackground,
        }}
      >
        <h2
          className="mb-6 text-xl font-bold tracking-tight sm:mb-8 sm:text-2xl"
          style={{ color: tc.textPrimary }}
        >
          Eligibility check timeline
        </h2>
        <Timeline items={d.timeline} />
      </section>
          </>
        )}

        {toastEl}
      </div>
    </div>
  )
}

export default function EligibilityResult({ providerMode = false }: { providerMode?: boolean }) {
  if (providerMode) {
    return <EligibilityResultContent providerMode />
  }

  return (
    <PatientFlowCogniThemeScope className="relative overflow-x-hidden">
      <EligibilityResultContent />
    </PatientFlowCogniThemeScope>
  )
}
