import { useEffect, useMemo, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { CheckCircle2, AlertTriangle, ArrowLeft, ShieldCheck } from 'lucide-react'
import Button from '../components/forms/Button'
import { ROUTES } from '../routes/routeMap'
import { buildEligibilityDashboardView } from '../services/eligibilityDashboardView'
import type { EligibilityResultRouteState } from '../services/mapPverifyToEligibilityView'

function asRecord(v: unknown): Record<string, unknown> | null {
  return v !== null && typeof v === 'object' && !Array.isArray(v)
    ? (v as Record<string, unknown>)
    : null
}

function firstNonEmpty(...values: unknown[]): string {
  for (const value of values) {
    const text = value != null ? String(value).trim() : ''
    if (text) return text
  }
  return '—'
}

function asArray(v: unknown): unknown[] {
  return Array.isArray(v) ? v : []
}

function networkCodeLabel(code: string): string {
  const upper = code.trim().toUpperCase()
  if (upper === 'Y') return 'In network'
  if (upper === 'N') return 'Out of network'
  if (upper === 'W') return 'Not set'
  return upper || 'Not set'
}

function isStatusType(type: string): boolean {
  return type.trim().toLowerCase().includes('status')
}

function MultiSelectFilter({
  label,
  options,
  selected,
  onChange,
}: {
  label: string
  options: string[]
  selected: string[]
  onChange: (values: string[]) => void
}) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement | null>(null)
  const selectedSet = useMemo(() => new Set(selected), [selected])

  useEffect(() => {
    const onDocClick = (event: MouseEvent) => {
      if (!rootRef.current) return
      if (!rootRef.current.contains(event.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', onDocClick)
    return () => document.removeEventListener('mousedown', onDocClick)
  }, [])

  const toggle = (value: string) => {
    if (selectedSet.has(value)) {
      onChange(selected.filter((x) => x !== value))
    } else {
      onChange([...selected, value])
    }
  }

  return (
    <div className="relative" ref={rootRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="inline-flex items-center gap-2 rounded-md border border-slate-700 bg-slate-800 px-2.5 py-1.5 text-xs text-slate-200 hover:border-slate-500"
      >
        <span>{label}</span>
        {selected.length > 0 ? (
          <span className="rounded bg-slate-700 px-1.5 py-0.5 text-[10px] text-slate-200">
            {selected.length} selected
          </span>
        ) : null}
      </button>
      {open && (
        <div className="absolute left-0 top-[calc(100%+6px)] z-20 w-56 rounded-md border border-slate-700 bg-slate-900 p-2 shadow-xl">
          <p className="mb-2 px-1 text-[11px] text-slate-400">Filter by {label.toLowerCase()}</p>
          <div className="max-h-48 space-y-1 overflow-y-auto pr-1 [scrollbar-width:thin] [&::-webkit-scrollbar]:w-1.5">
            {options.map((option) => (
              <label
                key={option}
                className="flex cursor-pointer items-center gap-2 rounded px-1 py-1 text-xs text-slate-200 hover:bg-slate-800"
              >
                <input
                  type="checkbox"
                  checked={selectedSet.has(option)}
                  onChange={() => toggle(option)}
                  className="h-3.5 w-3.5"
                />
                <span>{option}</span>
              </label>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

function getFamilySummary(raw: Record<string, unknown>, patientName: string) {
  const demo = asRecord(raw.DemographicInfo)
  const sub = demo ? asRecord(demo.Subscriber) : null
  const subscriberName = firstNonEmpty(
    sub?.FullName,
    [sub?.Firstname, sub?.Lastname_R].filter(Boolean).join(' ')
  )

  let memberId = '—'
  const identification = sub?.Identification
  if (Array.isArray(identification)) {
    for (const row of identification) {
      const rec = asRecord(row)
      if (!rec) continue
      if (String(rec.Type ?? '').toLowerCase().includes('member') && rec.Code != null) {
        memberId = String(rec.Code).trim() || '—'
        break
      }
    }
  }

  const depsRaw = demo?.Dependents
  const dependents = Array.isArray(depsRaw)
    ? depsRaw
        .map((item) => asRecord(item))
        .filter((item): item is Record<string, unknown> => Boolean(item))
        .map((item) =>
          firstNonEmpty(item.FullName, [item.Firstname, item.Lastname_R].filter(Boolean).join(' '))
        )
        .filter((name) => name !== '—')
    : []

  const dependentCount = dependents.length
  const relationship = subscriberName !== '—' && subscriberName === patientName ? 'Self' : 'Dependent'

  return { subscriberName, memberId, dependentCount, relationship }
}

export default function EligibilityResultAi() {
  const location = useLocation()
  const navigate = useNavigate()
  const state = location.state as EligibilityResultRouteState | null
  const raw = state?.rawResponse ?? null
  const intake = state?.intakeContext

  const dashboard = useMemo(() => {
    if (!raw) return null
    return buildEligibilityDashboardView(raw, {
      patientName: intake?.patientName ?? '',
      cptHcpcCode: intake?.cptHcpcCode ?? '',
      serviceDateFrom: intake?.serviceDateFrom ?? '',
      serviceDateTo: intake?.serviceDateTo ?? '',
    })
  }, [raw, intake?.patientName, intake?.cptHcpcCode, intake?.serviceDateFrom, intake?.serviceDateTo])

  if (!raw || !dashboard) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-950 px-4">
        <div className="w-full max-w-lg rounded-2xl border border-slate-800 bg-slate-900 p-6 text-center">
          <h1 className="text-xl font-semibold text-slate-100">No eligibility result yet</h1>
          <p className="mt-2 text-sm text-slate-300">Run a check from the AI intake flow first.</p>
          <div className="mt-4">
            <Button type="button" variant="primary" onClick={() => navigate(ROUTES.PATIENT_AI_INTAKE)}>
              Back to AI Intake
            </Button>
          </div>
        </div>
      </div>
    )
  }

  const d = dashboard
  const family = getFamilySummary(raw, d.patientName)
  const [typeFilter, setTypeFilter] = useState<string[]>([])
  const [coverageLevelFilter, setCoverageLevelFilter] = useState<string[]>([])
  const [networkFilter, setNetworkFilter] = useState<string[]>([])
  const [benefitSearch, setBenefitSearch] = useState('')

  const benefitsRoot = useMemo(() => {
    const top = asRecord(raw)
    const nested = asRecord(top?.StediRawResponse)
    return nested ?? top ?? {}
  }, [raw])

  const benefitRows = useMemo(() => {
    const rows = asArray((benefitsRoot as Record<string, unknown>).benefitsInformation)
      .map((r) => asRecord(r))
      .filter((r): r is Record<string, unknown> => r !== null)
      .map((r) => ({
        code: firstNonEmpty(r.code),
        name: firstNonEmpty(r.name, r.code),
        type: firstNonEmpty(r.name, r.code),
        coverageLevel: firstNonEmpty(r.coverageLevel, 'Not set'),
        network: networkCodeLabel(firstNonEmpty(r.inPlanNetworkIndicatorCode, r.inPlanNetworkIndicator, '')),
        serviceTypes: asArray(r.serviceTypes).map((v) => String(v)).filter(Boolean),
        timeQualifier: firstNonEmpty(r.timeQualifier),
        amount: firstNonEmpty(r.benefitAmount),
        percent: firstNonEmpty(r.benefitPercent),
        additionalInfoItems: asArray(r.additionalInformation)
          .map((entry) => asRecord(entry))
          .filter((entry): entry is Record<string, unknown> => entry !== null)
          .map((entry) => firstNonEmpty(entry.description, ''))
          .filter((v) => v !== '—'),
        additionalInfo: asArray(r.additionalInformation)
          .map((entry) => asRecord(entry))
          .filter((entry): entry is Record<string, unknown> => entry !== null)
          .map((entry) => firstNonEmpty(entry.description, ''))
          .filter((v) => v !== '—')
          .join(' | '),
        insuranceType: firstNonEmpty(r.insuranceType, d.planType, ''),
      }))
    return rows
  }, [benefitsRoot, d.planType])

  const filteredBenefitRows = useMemo(() => {
    const query = benefitSearch.trim().toLowerCase()
    return benefitRows.filter((row) => {
      if (typeFilter.length > 0 && !typeFilter.includes(row.type)) return false
      if (coverageLevelFilter.length > 0 && !coverageLevelFilter.includes(row.coverageLevel)) {
        return false
      }
      if (networkFilter.length > 0 && !networkFilter.includes(row.network)) return false
      if (query) {
        const haystack = [
          row.code,
          row.name,
          row.coverageLevel,
          row.network,
          row.serviceTypes.join(' '),
          row.timeQualifier,
          row.amount,
          row.percent,
          row.additionalInfo,
        ]
          .join(' ')
          .toLowerCase()
        if (!haystack.includes(query)) return false
      }
      return true
    })
  }, [benefitRows, benefitSearch, coverageLevelFilter, networkFilter, typeFilter])

  const groupedBenefitRows = useMemo(() => {
    return filteredBenefitRows.map((row, index, rows) => {
      const prev = index > 0 ? rows[index - 1] : null
      const showType = !prev || prev.type !== row.type
      const typeRowSpan = showType ? rows.slice(index).filter((r) => r.type === row.type).length : 0
      const showCoverageLevel = !prev || prev.type !== row.type || prev.coverageLevel !== row.coverageLevel
      const coverageLevelRowSpan = showCoverageLevel
        ? rows
            .slice(index)
            .filter((r) => r.type === row.type && r.coverageLevel === row.coverageLevel).length
        : 0
      return { row, showType, typeRowSpan, showCoverageLevel, coverageLevelRowSpan }
    })
  }, [filteredBenefitRows])

  const benefitVariation2Groups = useMemo(() => {
    const map = new Map<
      string,
      {
        type: string
        coverageLevel: string
        network: string
        coverageLines: string[]
        benefitLines: string[]
      }
    >()

    for (const row of filteredBenefitRows) {
      const key = `${row.type}__${row.coverageLevel}__${row.network}`
      if (!map.has(key)) {
        map.set(key, {
          type: row.type,
          coverageLevel: row.coverageLevel,
          network: row.network,
          coverageLines: [],
          benefitLines: [],
        })
      }
      const target = map.get(key)!
      const coverageText = isStatusType(row.type)
        ? d.coverageActive
          ? 'Active coverage'
          : 'Coverage needs review'
        : [row.amount, row.percent].filter((v) => v && v !== '—').join(' · ') || 'Not set'
      if (!target.coverageLines.includes(coverageText)) {
        target.coverageLines.push(coverageText)
      }

      if (isStatusType(row.type)) {
        const statusBenefit = row.insuranceType
          ? `Insurance type: ${row.insuranceType}`
          : 'Insurance type: Not set'
        if (!target.benefitLines.includes(statusBenefit)) {
          target.benefitLines.push(statusBenefit)
        }
      } else if (row.additionalInfoItems.length > 0) {
        for (const info of row.additionalInfoItems) {
          if (!target.benefitLines.includes(info)) {
            target.benefitLines.push(info)
          }
        }
      } else {
        const fallback = row.timeQualifier || 'Not set'
        if (!target.benefitLines.includes(fallback)) {
          target.benefitLines.push(fallback)
        }
      }
    }

    return Array.from(map.values())
  }, [d.coverageActive, filteredBenefitRows])

  const typeOptions = useMemo(
    () => Array.from(new Set(benefitRows.map((r) => r.type).filter(Boolean))).sort(),
    [benefitRows]
  )
  const coverageLevelOptions = useMemo(
    () => Array.from(new Set(benefitRows.map((r) => r.coverageLevel).filter(Boolean))).sort(),
    [benefitRows]
  )
  const networkOptions = useMemo(
    () => Array.from(new Set(benefitRows.map((r) => r.network).filter(Boolean))).sort(),
    [benefitRows]
  )

  const summaryRows = [
    { label: 'Member ID', value: d.patientId || family.memberId },
    { label: 'Plan Type', value: d.planType || '—' },
    { label: 'Service Code', value: d.serviceCode || '—' },
    { label: 'Service Date', value: d.serviceDate || '—' },
    { label: 'Effective Date', value: d.effectiveDateDisplay || '—' },
    { label: 'Check Date', value: d.checkDateDisplay || '—' },
  ]

  return (
    <div className="min-h-screen bg-slate-950 px-4 py-8 text-slate-100 sm:px-6">
      <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_12%_18%,rgba(124,58,237,.2),transparent_35%),radial-gradient(circle_at_88%_22%,rgba(14,165,233,.18),transparent_33%),radial-gradient(circle_at_52%_95%,rgba(99,102,241,.14),transparent_35%)]" />
      <div className="relative mx-auto max-w-6xl space-y-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h1 className="text-2xl font-semibold">Eligibility Summary</h1>
          <Button type="button" variant="outline" onClick={() => navigate(ROUTES.PATIENT_AI_INTAKE)}>
            <span className="inline-flex items-center gap-2"><ArrowLeft className="h-4 w-4" />New Check</span>
          </Button>
        </div>

        <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5">
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div>
              <p className="text-xs uppercase tracking-wide text-slate-400">Patient</p>
              <p className="text-3xl font-bold">{d.patientName || '—'}</p>
              <p className="mt-1 text-sm text-slate-300">{d.payor || '—'} {d.planName ? `· ${d.planName}` : ''}</p>
            </div>
            <div className="space-y-2">
              {d.statusEligible ? (
                <span className="inline-flex items-center gap-2 rounded-full bg-emerald-100 px-4 py-2 text-emerald-900">
                  <CheckCircle2 className="h-5 w-5" /> Eligible
                </span>
              ) : (
                <span className="inline-flex items-center gap-2 rounded-full bg-amber-100 px-4 py-2 text-amber-900">
                  <AlertTriangle className="h-5 w-5" /> Review Required
                </span>
              )}
              <p className="text-right text-xs text-slate-300">
                {d.networkInNetwork ? 'In-network' : 'Out-of-network'} ·{' '}
                {d.coverageActive ? 'Coverage active' : 'Coverage needs review'}
              </p>
            </div>
          </div>
        </section>

        <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5">
          <div className="mb-4 inline-flex items-center gap-2 text-violet-300">
            <ShieldCheck className="h-5 w-5" />
            <h2 className="text-lg font-semibold text-slate-100">Coverage Snapshot</h2>
          </div>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {summaryRows.map((row) => (
              <div key={row.label} className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
                <p className="text-xs uppercase tracking-wide text-slate-400">{row.label}</p>
                <p className="mt-1 text-slate-100">{row.value}</p>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5">
          <h2 className="mb-3 text-lg font-semibold text-slate-100">Financial Summary</h2>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Copay</p>
              <p className="mt-1 text-slate-100">${d.financial.copay.toFixed(2)}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Deductible Remaining</p>
              <p className="mt-1 text-slate-100">${d.financial.deductibleRemaining.toFixed(2)}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Out-of-pocket Remaining</p>
              <p className="mt-1 text-slate-100">${d.financial.outOfPocketRemaining.toFixed(2)}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Coinsurance</p>
              <p className="mt-1 text-slate-100">{d.financial.coinsurance || '—'}</p>
            </div>
          </div>
        </section>

        <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5">
          <h2 className="mb-3 text-lg font-semibold text-slate-100">Family</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Subscriber</p>
              <p className="mt-1 text-slate-100">{family.subscriberName}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Member ID</p>
              <p className="mt-1 text-slate-100">{family.memberId}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Patient Relationship</p>
              <p className="mt-1 text-slate-100">{family.relationship}</p>
            </div>
            <div className="rounded-xl border border-slate-700 bg-slate-800/70 p-3 text-sm">
              <p className="text-xs uppercase tracking-wide text-slate-400">Dependents</p>
              <p className="mt-1 text-slate-100">{family.dependentCount}</p>
            </div>
          </div>
        </section>

        {benefitRows.length > 0 && (
          <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5">
            <h2 className="mb-3 text-lg font-semibold text-slate-100">Benefits Filters</h2>
            <div className="mb-3">
              <input
                value={benefitSearch}
                onChange={(e) => setBenefitSearch(e.target.value)}
                placeholder="Search benefits..."
                className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-xs text-slate-100 placeholder:text-slate-400 sm:max-w-sm sm:text-sm"
              />
            </div>
            <div className="mb-4 flex flex-wrap items-center gap-2">
              <MultiSelectFilter
                label="Type"
                options={typeOptions}
                selected={typeFilter}
                onChange={setTypeFilter}
              />
              <MultiSelectFilter
                label="Coverage level"
                options={coverageLevelOptions}
                selected={coverageLevelFilter}
                onChange={setCoverageLevelFilter}
              />
              <MultiSelectFilter
                label="Network"
                options={networkOptions}
                selected={networkFilter}
                onChange={setNetworkFilter}
              />
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setBenefitSearch('')
                  setTypeFilter([])
                  setCoverageLevelFilter([])
                  setNetworkFilter([])
                }}
              >
                Clear filters
              </Button>
            </div>

            <div className="mb-3">
              <h3 className="text-sm font-semibold text-slate-200">
                STC {d.serviceCode || '30'} Health Benefit Plan Coverage
              </h3>
            </div>
            <div className="overflow-x-auto rounded-xl border border-slate-700">
              <table className="w-full min-w-[900px] text-left text-xs sm:text-sm">
                <thead className="bg-slate-800/80">
                  <tr>
                    <th className="border-r border-slate-700 px-3 py-2 text-xs uppercase tracking-wide text-slate-300">Type</th>
                    <th className="border-r border-slate-700 px-3 py-2 text-xs uppercase tracking-wide text-slate-300">Coverage level</th>
                    <th className="border-r border-slate-700 px-3 py-2 text-xs uppercase tracking-wide text-slate-300">Network indicator</th>
                    <th className="border-r border-slate-700 px-3 py-2 text-xs uppercase tracking-wide text-slate-300">Coverage</th>
                    <th className="px-3 py-2 text-xs uppercase tracking-wide text-slate-300">Benefit</th>
                  </tr>
                </thead>
                <tbody>
                  {groupedBenefitRows.map(({ row, showType, typeRowSpan, showCoverageLevel, coverageLevelRowSpan }, idx) => (
                    <tr key={`${row.code}-${row.name}-${idx}`} className="border-t border-slate-800 align-top">
                      {showType ? (
                        <td rowSpan={typeRowSpan} className="border-r border-slate-700 px-3 py-2 text-slate-100">
                          {row.type}
                        </td>
                      ) : null}
                      {showCoverageLevel ? (
                        <td rowSpan={coverageLevelRowSpan} className="border-r border-slate-700 px-3 py-2 text-slate-200">
                          {row.coverageLevel}
                        </td>
                      ) : null}
                      <td className="border-r border-slate-700 px-3 py-2 text-slate-200">{row.network}</td>
                      <td className="border-r border-slate-700 px-3 py-2 text-slate-200">
                        {isStatusType(row.type)
                          ? d.coverageActive
                            ? 'Active coverage'
                            : 'Coverage needs review'
                          : [row.amount, row.percent].filter((v) => v && v !== '—').join(' · ') || '—'}
                      </td>
                      <td className="px-3 py-2 text-slate-200">
                        {isStatusType(row.type) ? (
                          row.insuranceType ? `Insurance type : ${row.insuranceType}` : 'Insurance type : —'
                        ) : row.additionalInfoItems.length > 0 ? (
                          <div className="space-y-1">
                            {row.additionalInfoItems.map((item, itemIdx) => (
                              <div key={`${row.code}-${idx}-${itemIdx}`} className="leading-5">
                                {item}
                              </div>
                            ))}
                          </div>
                        ) : (
                          row.timeQualifier || 'Not set'
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filteredBenefitRows.length === 0 && (
                <p className="px-3 py-4 text-sm text-slate-400">No benefits match current filters.</p>
              )}
            </div>

            <div className="mt-6 rounded-xl border border-slate-700 bg-slate-800/40 p-4">
              <h3 className="text-sm font-semibold text-slate-100">
                Benefits section (Variation 2 - user friendly preview)
              </h3>
              <p className="mt-1 text-xs text-slate-300">
                Same data shown in a simpler grouped format for client demo.
              </p>

              {benefitVariation2Groups.length === 0 ? (
                <p className="mt-3 text-sm text-slate-400">No benefit rows to preview.</p>
              ) : (
                <div className="mt-4 grid gap-3 sm:grid-cols-2">
                  {benefitVariation2Groups.map((group, idx) => (
                    <div key={`${group.type}-${group.coverageLevel}-${group.network}-${idx}`} className="rounded-lg border border-slate-700 bg-slate-900/70 p-3">
                      <div className="mb-2 flex flex-wrap items-center gap-2">
                        <span className="rounded-md bg-slate-700 px-2 py-0.5 text-xs font-medium text-slate-100">
                          {group.type}
                        </span>
                        <span className="text-xs text-slate-300">{group.coverageLevel}</span>
                        <span className="text-xs text-slate-400">|</span>
                        <span className="text-xs text-slate-300">{group.network}</span>
                      </div>
                      <div className="space-y-2 text-xs">
                        <div>
                          <p className="font-semibold uppercase tracking-wide text-slate-400">Coverage</p>
                          <ul className="mt-1 list-disc space-y-0.5 pl-4 text-slate-200">
                            {group.coverageLines.map((line, lineIdx) => (
                              <li key={`${idx}-cov-${lineIdx}`}>{line}</li>
                            ))}
                          </ul>
                        </div>
                        <div>
                          <p className="font-semibold uppercase tracking-wide text-slate-400">Benefit</p>
                          <ul className="mt-1 list-disc space-y-0.5 pl-4 text-slate-200">
                            {group.benefitLines.map((line, lineIdx) => (
                              <li key={`${idx}-ben-${lineIdx}`}>{line}</li>
                            ))}
                          </ul>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </section>
        )}
      </div>
    </div>
  )
}
