import { env } from '../config/env'

const API_BASE_URL = env.apiBaseUrl()
const AUTH_STORAGE_KEY = 'healthlynk_auth'
export const AUTH_EXPIRED_EVENT = 'healthlynk:auth-expired'

type StoredAuth = {
  accessToken?: string
}

function readAccessToken(): string | null {
  try {
    const raw = localStorage.getItem(AUTH_STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw) as StoredAuth
    return typeof parsed.accessToken === 'string' && parsed.accessToken.trim()
      ? parsed.accessToken
      : null
  } catch {
    return null
  }
}

function buildUrl(path: string): string {
  const normalizedPath = path.startsWith('/') ? path : `/${path}`
  return `${API_BASE_URL}${normalizedPath}`
}

function readErrorMessage(body: unknown): string | null {
  if (!body || typeof body !== 'object') return null
  const record = body as Record<string, unknown>
  const candidates = [record.message, record.msg, record.error, record.detail]
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim()) {
      return candidate.trim()
    }
  }
  return null
}

function notifyAuthExpired() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new Event(AUTH_EXPIRED_EVENT))
  }
}

export async function apiRequest(path: string, init: RequestInit = {}): Promise<Response> {
  const token = readAccessToken()
  const headers = new Headers(init.headers)

  if (token && !headers.has('Authorization')) {
    headers.set('Authorization', `Bearer ${token}`)
  }

  return fetch(buildUrl(path), {
    ...init,
    headers,
  })
}

export async function apiJsonRequest<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers)
  if (!headers.has('Content-Type') && init.body != null) {
    headers.set('Content-Type', 'application/json')
  }

  const response = await apiRequest(path, {
    ...init,
    headers,
  })

  const text = await response.text()
  let body: T | null = null
  if (text) {
    try {
      body = JSON.parse(text) as T
    } catch {
      if (!response.ok) {
        throw new Error(`Request failed (${response.status})`)
      }
      throw new Error('Response returned invalid JSON.')
    }
  }

  if (!response.ok) {
    const fallback = `Request failed (${response.status})`
    const message = readErrorMessage(body)
    if (response.status === 401 && message && /token has expired/i.test(message)) {
      notifyAuthExpired()
      throw new Error(message)
    }
    if (message) {
      throw new Error(message)
    }
    throw new Error(fallback)
  }
  return (body ?? ({} as T)) as T
}

export { API_BASE_URL }
