import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import { apiJsonRequest, AUTH_EXPIRED_EVENT } from '../services/apiClient'

const STORAGE_KEY = 'healthlynk_auth'

export type AuthUser = {
  id: string
  username: string
  displayName: string
  role: string
  isActive: boolean
}

type AuthStorage = {
  accessToken: string
  user: AuthUser
}

type AuthContextValue = {
  user: AuthUser | null
  accessToken: string | null
  isAuthenticated: boolean
  isLoading: boolean
  login: (username: string, password: string) => Promise<{ ok: boolean; error?: string }>
  logout: () => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

function readStoredUser(): AuthUser | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw) as Partial<AuthStorage>
    if (parsed?.user && parsed.accessToken && typeof parsed.accessToken === 'string') {
      return parsed.user
    }
  } catch {
    /* ignore */
  }
  return null
}

function readStoredToken(): string | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw) as Partial<AuthStorage>
    if (parsed?.accessToken && typeof parsed.accessToken === 'string') {
      return parsed.accessToken
    }
  } catch {
    /* ignore */
  }
  return null
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null)
  const [accessToken, setAccessToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    setUser(readStoredUser())
    setAccessToken(readStoredToken())
    setIsLoading(false)
  }, [])

  const login = useCallback(async (username: string, password: string) => {
    const trimmedUsername = username.trim()
    if (!trimmedUsername || !password) {
      return { ok: false, error: 'Enter username and password.' }
    }

    try {
      const parsed = await apiJsonRequest<{
        data?: {
          access_token?: string
          user?: {
            display_name?: string
            id?: string
            is_active?: boolean
            role?: string
            username?: string
          }
        }
        message?: string
      }>('/auth/login', {
        method: 'POST',
        body: JSON.stringify({
          username: trimmedUsername,
          password,
        }),
      })

      const token = parsed?.data?.access_token
      const apiUser = parsed?.data?.user
      if (!token || !apiUser?.id || !apiUser?.username) {
        return { ok: false, error: parsed?.message || 'Sign in failed.' }
      }

      const nextUser: AuthUser = {
        id: apiUser.id,
        username: apiUser.username,
        displayName: apiUser.display_name || apiUser.username,
        role: apiUser.role || 'user',
        isActive: Boolean(apiUser.is_active),
      }

      const storageValue: AuthStorage = {
        accessToken: token,
        user: nextUser,
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(storageValue))
      setAccessToken(token)
      setUser(nextUser)
      return { ok: true }
    } catch (error) {
      if (error instanceof Error) {
        return { ok: false, error: error.message || 'Sign in failed.' }
      }
      return { ok: false, error: 'Unable to reach server. Please try again.' }
    }
  }, [])

  const logout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY)
    setAccessToken(null)
    setUser(null)
  }, [])

  useEffect(() => {
    const onAuthExpired = () => {
      logout()
    }
    window.addEventListener(AUTH_EXPIRED_EVENT, onAuthExpired)
    return () => {
      window.removeEventListener(AUTH_EXPIRED_EVENT, onAuthExpired)
    }
  }, [logout])

  const value = useMemo<AuthContextValue>(
    () => ({
      user,
      accessToken,
      isAuthenticated: !!user,
      isLoading,
      login,
      logout,
    }),
    [user, accessToken, isLoading, login, logout]
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) {
    throw new Error('useAuth must be used within AuthProvider')
  }
  return ctx
}
