/**
 * pVerify OAuth token + authenticated fetch helpers.
 * Token endpoint expects OAuth2 client_credentials as x-www-form-urlencoded.
 */
import { env } from '../config/env'

export type PverifyTokenResponse = {
  access_token: string;
  token_type: string;
  expires_in: number;
};

type CachedToken = {
  accessToken: string;
  expiresAtMs: number;
};

let cache: CachedToken | null = null;

const TOKEN_PATH = "/Token";
const TOKEN_SKEW_MS = 60_000;

function getApiBase(): string {
  return env.pverifyApiBase();
}

function getClientApiId(): string {
  return env.pverifyClientApiId();
}

/** Optional portal username for tenants that validate `Client-User-Name` strictly. */
function getPverifyClientUserName(): string {
  return env.pverifyClientUserName();
}

export function assertPverifyEnv(): void {
  const id = env.pverifyClientId();
  const secret = env.pverifyClientSecret();
  if (!id || !secret) {
    throw new Error(
      "Set VITE_PVERIFY_CLIENT_ID and VITE_PVERIFY_CLIENT_SECRET in .env (see .env.example)."
    );
  }
  env.pverifyApiBase();
}

async function fetchNewToken(): Promise<PverifyTokenResponse> {
  assertPverifyEnv();
  const clientId = env.pverifyClientId();
  const clientSecret = env.pverifyClientSecret();
  const base = getApiBase();
  const body = new URLSearchParams({
    grant_type: "client_credentials",
    client_id: clientId,
    client_secret: clientSecret,
  });

  const res = await fetch(`${base}${TOKEN_PATH}`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });

  const text = await res.text();
  let data: unknown;
  try {
    data = JSON.parse(text) as unknown;
  } catch {
    throw new Error(`pVerify Token: non-JSON response (${res.status})`);
  }

  if (!res.ok) {
    const err = data as { error?: string; error_description?: string };
    const msg = [err.error, err.error_description].filter(Boolean).join(" — ");
    throw new Error(msg || `pVerify Token failed (${res.status})`);
  }

  const token = data as PverifyTokenResponse;
  if (!token.access_token || typeof token.expires_in !== "number") {
    throw new Error("pVerify Token: unexpected response shape");
  }
  return token;
}

/**
 * Returns a valid access token, reusing the in-memory cache until near expiry.
 */
export async function getPverifyAccessToken(): Promise<string> {
  const now = Date.now();
  if (cache && cache.expiresAtMs > now + TOKEN_SKEW_MS) {
    return cache.accessToken;
  }
  const t = await fetchNewToken();
  cache = {
    accessToken: t.access_token,
    expiresAtMs: now + Math.max(0, t.expires_in) * 1000,
  };
  return cache.accessToken;
}

/** Headers for pVerify APIs after you have a bearer token. */
export function pverifyAuthHeaders(accessToken: string): HeadersInit {
  const clientApiId = getClientApiId();
  if (!clientApiId) {
    throw new Error("Set VITE_PVERIFY_CLIENT_API_ID or VITE_PVERIFY_CLIENT_ID.");
  }
  const headers: Record<string, string> = {
    Authorization: `Bearer ${accessToken}`,
    "Client-API-Id": clientApiId,
    "Content-Type": "application/json",
  };
  const userName = getPverifyClientUserName();
  if (userName) headers["Client-User-Name"] = userName;
  return headers;
}

/**
 * GET/POST/etc. against pVerify with automatic token + standard headers.
 * @param path API path starting with / (e.g. "/EligibilitySummary")
 */
export async function pverifyFetch(
  path: string,
  init: RequestInit = {}
): Promise<Response> {
  const token = await getPverifyAccessToken();
  const base = getApiBase();
  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;
  const headers = new Headers(init.headers);
  const auth = pverifyAuthHeaders(token);
  for (const [k, v] of Object.entries(auth)) {
    if (!headers.has(k)) headers.set(k, v);
  }
  return fetch(url, { ...init, headers });
}

/** Clear cached token (e.g. after 401). */
export function clearPverifyTokenCache(): void {
  cache = null;
}

/**
 * Path to eligibility PDF report for a RequestID.
 * Default: `/API/Report/EligibilityPDFReport/{id}` — same `/API/` prefix as GetAllPayers.
 * Legacy `/Report/EligibilityPDFReport/...` often returns HTTP 404 on testapi.pverify.com.
 *
 * Override: `VITE_PVERIFY_ELIGIBILITY_PDF_PREFIX=/api/Report/EligibilityPDFReport` (no trailing slash)
 */
export function buildEligibilityPdfReportPath(
  requestId: number | string
): string {
  const id = encodeURIComponent(String(requestId).trim());
  const prefix =
    env.pverifyEligibilityPdfPrefix().replace(/\/$/, "");
  return `${prefix}/${id}`;
}

/** Full URL for the eligibility PDF endpoint (uses same base as token + eligibility). */
export function buildEligibilityPdfReportUrl(
  requestId: number | string
): string {
  return `${getApiBase()}${buildEligibilityPdfReportPath(requestId)}`;
}

/**
 * GET/POST Eligibility PDF for RequestID from EligibilitySummary.
 * Matches pVerify REST samples: Authorization, Client-API-Id, Client-User-Name,
 * Content-Type: application/json (see pVerify/restapijava EligibilitySummary.java).
 */
export async function fetchEligibilityPdfReport(
  requestId: number
): Promise<Blob> {
  assertPverifyEnv();
  const url = buildEligibilityPdfReportUrl(requestId);

  const pdfHeaders = (token: string): HeadersInit => ({
    ...(() => {
      const h: Record<string, string> = {
        Authorization: `Bearer ${token}`,
        "Client-API-Id": getClientApiId(),
        "Content-Type": "application/json",
        Accept: "application/pdf, application/json, */*",
      };
      const userName = getPverifyClientUserName();
      if (userName) h["Client-User-Name"] = userName;
      return h;
    })(),
  });

  const requestPdf = async (
    token: string,
    method: "GET" | "POST"
  ): Promise<Response> =>
    fetch(url, {
      method,
      headers: pdfHeaders(token),
      body: method === "POST" ? "{}" : undefined,
    });

  const with401Retry = async (
    method: "GET" | "POST"
  ): Promise<Response> => {
    let token = await getPverifyAccessToken();
    let res = await requestPdf(token, method);
    if (res.status === 401) {
      clearPverifyTokenCache();
      token = await getPverifyAccessToken();
      res = await requestPdf(token, method);
    }
    return res;
  };

  let res = await with401Retry("GET");
  const ct0 = res.headers.get("content-type") ?? "";
  if (ct0.includes("application/json")) {
    const text = await res.text();
    let msg = text;
    try {
      const j = JSON.parse(text) as { Error?: string };
      msg = (j.Error || text).trim();
    } catch {
      /* keep text */
    }
    if (/required headers|headers data missing/i.test(msg)) {
      res = await with401Retry("POST");
    } else {
      throw new Error(msg || "PDF request failed");
    }
  }

  const ct = res.headers.get("content-type") ?? "";
  if (!res.ok) {
    const text = await res.text();
    let msg = text;
    try {
      const j = JSON.parse(text) as { Error?: string };
      msg = (j.Error || text).trim();
    } catch {
      /* keep */
    }
    throw new Error(msg || `PDF request failed (${res.status})`);
  }

  if (ct.includes("application/json")) {
    const text = await res.text();
    let msg = text;
    try {
      const j = JSON.parse(text) as { Error?: string };
      msg = (j.Error || text).trim();
    } catch {
      /* keep */
    }
    throw new Error(msg || "PDF request returned JSON instead of a file");
  }

  return res.blob();
}
